    84	static bt_status_t parse_bt_adv_data(uint8_t* raw, uint16_t raw_len,
    85	    struct bt_data* out, size_t out_max, size_t* out_size)
    86	{
    87	    size_t index;
    88	    uint8_t item_len;
    89	
    90	    if (!out || !out_size || out_max == 0) {
    91	        return BT_STATUS_PARM_INVALID;
    92	    }
    93	
    94	    *out_size = 0;
    95	
    96	    if (!raw || raw_len == 0) {
    97	        return BT_STATUS_SUCCESS;
    98	    }
    99	
   100	    for (index = 0; index < raw_len;) {
   101	        item_len = raw[index];
   102	        if (item_len == 0) {
   103	            break;
   104	        }
   105	
   106	        if (item_len < 2) {
   107	            BT_LOGE("%s, invalid adv data item len:%d", __func__, item_len);
   108	            return BT_STATUS_PARM_INVALID;
   109	        }
   110	
   111	        if (index + 1 + item_len > raw_len) {
   112	            BT_LOGE("%s, adv data overflow: raw_len=%d idx=%d item_len=%d", __func__,
   113	                raw_len, index, item_len);
   114	            return BT_STATUS_PARM_INVALID;
   115	        }
   116	
   117	        if (*out_size >= out_max) {
   118	            BT_LOGE("too many segments: out_max=%d idx=%d", out_max, index);
   119	            return BT_STATUS_PARM_INVALID;
   120	        }
   121	
   122	        out[*out_size].data_len = item_len - 1;
   123	        out[*out_size].type = raw[index + 1];
   124	        out[*out_size].data = &raw[index + 2];
   125	        index += out[*out_size].data_len + 2;
   126	        (*out_size)++;
   127	    }
   128	
   129	    return BT_STATUS_SUCCESS;
   130	}
