   144	        return;
   145	    }
   146	
   147	    if (adv_set->delete_pending) {
   148	        return;
   149	    }
   150	
   151	    adv_set->delete_pending = true;
   152	    req = sal_adapter_req(0, adv_set->adv_id, STACK_CALL(cleanup_terminated_adv));
   153	    if (!req) {
   154	        adv_set->delete_pending = false;
   155	        BT_LOGE("%s, req null", __func__);
   156	        return;
   157	    }
   158	
   159	    BT_LOGD("sal adv: defer terminated cleanup id=%u", adv_set->adv_id);
   160	    if (sal_send_req(req) != BT_STATUS_SUCCESS) {
   161	        adv_set->delete_pending = false;
   162	    }
   163	}
