   262	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE:
   263	    default:
   264	        param->options |= BT_LE_ADV_OPT_NONE;
   265	    }
   266	
   267	    param->interval_min = params->interval;
   268	    param->interval_max = params->interval;
   269	
   270	    if (params->adv_type == BT_LE_ADV_DIRECT_IND
   271	        || params->adv_type == BT_LE_EXT_ADV_DIRECT_IND
   272	        || params->adv_type == BT_LE_LEGACY_ADV_DIRECT_IND) {
