   463	            ret = BT_STATUS_FAIL;
   464	            goto done;
   465	        }
   466	    } else {
   467	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: legacy start begin id=%u\n", req->adv_id);
   468	        ret = bt_le_adv_start(&req->adpt.start_adv.param, ad_size > 0 ? ad : NULL, ad_size,
   469	            sd_size > 0 ? sd : NULL, sd_size);
   470	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: legacy start returned status=%d\n", ret);
