   529	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=adv_copy status=%d\n", BT_STATUS_NOMEM);
   530	            BT_LOGE("%s, malloc fail", __func__);
   531	            ret = BT_STATUS_NOMEM;
   532	            goto error;
   533	        }
   534	
   535	        memcpy(req->adpt.start_adv.adv_data, adv_data, adv_len);
   536	        req->adpt.start_adv.adv_len = adv_len;
   537	    } else {
   538	        req->adpt.start_adv.adv_data = NULL;
   539	        req->adpt.start_adv.adv_len = 0;
   540	    }
   541	
   542	    if ((((req->adpt.start_adv.param.options & BT_LE_ADV_OPT_SCANNABLE) && ext_adv)
   543	            || !ext_adv)
   544	        && scan_rsp_data && scan_rsp_len > 0) {
   545	        req->adpt.start_adv.scan_rsp_data = malloc(scan_rsp_len);
   546	        if (!req->adpt.start_adv.scan_rsp_data) {
   547	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=scan_rsp_copy status=%d\n", BT_STATUS_NOMEM);
   548	            BT_LOGE("%s, malloc fail", __func__);
   549	            ret = BT_STATUS_NOMEM;
   550	            goto error;
   551	        }
   552	
   553	        memcpy(req->adpt.start_adv.scan_rsp_data, scan_rsp_data, scan_rsp_len);
   554	        req->adpt.start_adv.scan_rsp_len = scan_rsp_len;
   555	    } else {
   556	        req->adpt.start_adv.scan_rsp_data = NULL;
   557	        req->adpt.start_adv.scan_rsp_len = 0;
   558	    }
   559	
   560	    if (params->duration) {
   561	        req->adpt.start_adv.ext_param.timeout = params->duration;
   562	    }
   563	
   564	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: service-loop post begin id=%u\n", adv_id);
   565	    ret = sal_send_req(req);
   566	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: service-loop post returned status=%d\n", ret);
   567	    return ret;
   568	
   569	error:
   570	    if (req->adpt.start_adv.adv_data)
   571	        free(req->adpt.start_adv.adv_data);
   572	    if (req->adpt.start_adv.scan_rsp_data)
   573	        free(req->adpt.start_adv.scan_rsp_data);
   574	    free(req);
   575	    return ret;
   576	}
