   406	static void STACK_CALL(start_adv)(void* args)
   407	{
   408	    sal_adapter_req_t* req = args;
   409	    struct bt_le_ext_adv* adv;
   410	    int ret;
   411	    struct bt_data ad[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   412	    struct bt_data sd[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   413	    size_t ad_size = 0;
   414	    size_t sd_size = 0;
   415	    bool ext_supported = bt_le_ext_adv_is_supported();
   416	
   417	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: execute id=%u\n", req->adv_id);
   418	
   419	    ret = parse_bt_adv_data(req->adpt.start_adv.adv_data, req->adpt.start_adv.adv_len,
   420	        ad, ARRAY_SIZE(ad), &ad_size);
   421	    if (ret) {
   422	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_adv status=%d\n", ret);
   423	        BT_LOGE("%s, parse adv_data fail, err:%d", __func__, ret);
   424	        goto done;
   425	    }
   426	
   427	    ret = parse_bt_adv_data(req->adpt.start_adv.scan_rsp_data, req->adpt.start_adv.scan_rsp_len,
   428	        sd, ARRAY_SIZE(sd), &sd_size);
   429	    if (ret) {
   430	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_scan_rsp status=%d\n", ret);
   430	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_scan_rsp status=%d\n", ret);
   431	        BT_LOGE("%s, parse scan_rsp_data fail, ret:%d", __func__, ret);
   432	        goto done;
   433	    }
   434	
   435	    if (ext_supported) {
   436	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue create begin id=%u\n", req->adv_id);
   437	        ret = zblue_le_ext_create(&req->adpt.start_adv.param, &adv, req->adv_id);
   438	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue create returned status=%d\n", ret);
   439	        if (ret) {
   440	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=create status=%d\n", ret);
   441	            BT_LOGE("%s, zblue le ext adv create fail, err:%d", __func__, ret);
   442	            ret = BT_STATUS_FAIL;
   443	            goto done;
   444	        }
   445	
   446	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue set_data begin id=%u\n", req->adv_id);
   447	        ret = bt_le_ext_adv_set_data(adv, ad_size > 0 ? ad : NULL, ad_size,
   448	            sd_size > 0 ? sd : NULL, sd_size);
