   186	        param->options |= BT_LE_ADV_OPT_CONN;
   187	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   188	        param->options |= BT_LE_ADV_OPT_NO_2M;
   189	        break;
   190	    case BT_LE_ADV_SCAN_IND:
   191	    case BT_LE_EXT_ADV_SCAN_IND:
   192	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   193	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   194	        param->options |= BT_LE_ADV_OPT_NO_2M;
   195	        break;
   196	    case BT_LE_ADV_DIRECT_IND:
   197	    case BT_LE_EXT_ADV_DIRECT_IND:
   198	        param->options |= BT_LE_ADV_OPT_CONN;
   199	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   200	        param->options |= BT_LE_ADV_OPT_NO_2M;
   201	        param->options |= BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY;
   202	        break;
   203	    case BT_LE_SCAN_RSP:
   204	    case BT_LE_EXT_SCAN_RSP:
   205	    case BT_LE_ADV_NONCONN_IND:
   206	    case BT_LE_EXT_ADV_NONCONN_IND:
   207	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   208	        param->options |= BT_LE_ADV_OPT_NO_2M;
   209	        break;
   210	    case BT_LE_LEGACY_ADV_IND:
   211	        param->options |= BT_LE_ADV_OPT_CONN;
   212	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   213	        break;
   214	    case BT_LE_LEGACY_ADV_DIRECT_IND:
   215	        param->options |= BT_LE_ADV_OPT_CONN;
   216	        break;
   217	    case BT_LE_LEGACY_ADV_SCAN_IND:
   218	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   219	        break;
   220	    case BT_LE_LEGACY_ADV_NONCONN_IND:
   220	    case BT_LE_LEGACY_ADV_NONCONN_IND:
   221	    case BT_LE_LEGACY_SCAN_RSP:
   222	        break;
   223	    default:
   224	        BT_LOGE("%s, le ext adv convert fail, invalid adv_type:%d", __func__, params->adv_type);
   225	        return BT_STATUS_PARM_INVALID;
   226	    }
   227	
   228	    switch (params->own_addr_type) {
   229	    case BT_LE_ADDR_TYPE_PUBLIC:
   230	        param->options |= BT_LE_ADV_OPT_USE_IDENTITY;
   231	        break;
   232	    }
   233	
   234	    switch (params->channel_map) {
   235	    case BT_LE_ADV_CHANNEL_37_ONLY:
   236	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_38 | BT_LE_ADV_OPT_DISABLE_CHAN_39;
   237	        break;
   238	    case BT_LE_ADV_CHANNEL_38_ONLY:
   239	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_37 | BT_LE_ADV_OPT_DISABLE_CHAN_39;
   240	        break;
   241	    case BT_LE_ADV_CHANNEL_39_ONLY:
   242	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_37 | BT_LE_ADV_OPT_DISABLE_CHAN_38;
   243	        break;
   244	    case BT_LE_ADV_CHANNEL_DEFAULT:
   245	        break;
   246	    default:
   247	        BT_LOGE("%s, le ext adv convert fail, invalid channel_map:%d", __func__, params->channel_map);
   248	        return BT_STATUS_PARM_INVALID;
   249	    }
   250	
   251	    switch (params->filter_policy) {
   252	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_SCAN:
   253	        param->options |= BT_LE_ADV_OPT_FILTER_SCAN_REQ;
   254	        break;
   255	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_CONNECTION:
   256	        param->options |= BT_LE_ADV_OPT_FILTER_CONN;
   257	        break;
   258	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_ALL:
   259	        param->options |= BT_LE_ADV_OPT_FILTER_SCAN_REQ;
   260	        param->options |= BT_LE_ADV_OPT_FILTER_CONN;
   261	        break;
   262	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE:
   263	    default:
   264	        param->options |= BT_LE_ADV_OPT_NONE;
   265	    }
   266	
   267	    param->interval_min = params->interval;
   268	    param->interval_max = params->interval;
   269	
   270	    if (params->adv_type == BT_LE_ADV_DIRECT_IND
   271	        || params->adv_type == BT_LE_EXT_ADV_DIRECT_IND
   272	        || params->adv_type == BT_LE_LEGACY_ADV_DIRECT_IND) {
   273	        addr.type = params->peer_addr_type;
   274	        memcpy(&addr.a, &params->peer_addr, sizeof(bt_address_t));
   275	        param->peer = &addr;
   276	    }
   277	
   278	    return BT_STATUS_SUCCESS;
   279	}
