   406	static void STACK_CALL(start_adv)(void* args)
   407	{
   408	    sal_adapter_req_t* req = args;
   409	    struct bt_le_ext_adv* adv;
   410	    int ret;
   411	    struct bt_data ad[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   412	    struct bt_data sd[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   413	    size_t ad_size = 0;
   414	    size_t sd_size = 0;
   415	    bool ext_supported = bt_le_ext_adv_is_supported();
   416	
   417	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: execute id=%u\n", req->adv_id);
   418	
   419	    ret = parse_bt_adv_data(req->adpt.start_adv.adv_data, req->adpt.start_adv.adv_len,
   420	        ad, ARRAY_SIZE(ad), &ad_size);
   421	    if (ret) {
   422	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_adv status=%d\n", ret);
   423	        BT_LOGE("%s, parse adv_data fail, err:%d", __func__, ret);
   424	        goto done;
   425	    }
   426	
   427	    ret = parse_bt_adv_data(req->adpt.start_adv.scan_rsp_data, req->adpt.start_adv.scan_rsp_len,
   428	        sd, ARRAY_SIZE(sd), &sd_size);
   429	    if (ret) {
   430	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_scan_rsp status=%d\n", ret);
   430	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_scan_rsp status=%d\n", ret);
   431	        BT_LOGE("%s, parse scan_rsp_data fail, ret:%d", __func__, ret);
   432	        goto done;
   433	    }
   434	
   435	    if (ext_supported) {
   436	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue create begin id=%u\n", req->adv_id);
   437	        ret = zblue_le_ext_create(&req->adpt.start_adv.param, &adv, req->adv_id);
   438	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue create returned status=%d\n", ret);
   439	        if (ret) {
   440	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=create status=%d\n", ret);
   441	            BT_LOGE("%s, zblue le ext adv create fail, err:%d", __func__, ret);
   442	            ret = BT_STATUS_FAIL;
   443	            goto done;
   444	        }
   445	
   446	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue set_data begin id=%u\n", req->adv_id);
   447	        ret = bt_le_ext_adv_set_data(adv, ad_size > 0 ? ad : NULL, ad_size,
   448	            sd_size > 0 ? sd : NULL, sd_size);
   449	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue set_data returned status=%d\n", ret);
   450	        if (ret) {
   451	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=set_data status=%d\n", ret);
   452	            BT_LOGE("%s, le ext adv set fail, err:%d", __func__, ret);
   453	            ret = BT_STATUS_FAIL;
   454	            goto done;
   455	        }
   456	
   457	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue enable begin id=%u\n", req->adv_id);
   458	        ret = bt_le_ext_adv_start(adv, &req->adpt.start_adv.ext_param);
   459	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue enable returned status=%d\n", ret);
   460	        if (ret) {
   461	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=enable status=%d\n", ret);
   462	            BT_LOGE("%s, le ext adv start fail, err:%d", __func__, ret);
   463	            ret = BT_STATUS_FAIL;
   464	            goto done;
   465	        }
   466	    } else {
   467	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: legacy start begin id=%u\n", req->adv_id);
   468	        ret = bt_le_adv_start(&req->adpt.start_adv.param, ad_size > 0 ? ad : NULL, ad_size,
   469	            sd_size > 0 ? sd : NULL, sd_size);
   470	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: legacy start returned status=%d\n", ret);
   471	        if (ret) {
   472	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=legacy_start status=%d\n", ret);
   473	            BT_LOGE("%s, legacy adv start fail, err:%d", __func__, ret);
   474	            ret = BT_STATUS_FAIL;
   475	            goto done;
   476	        }
   477	    }
   478	
   479	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: state callback begin id=%u\n", req->adv_id);
   480	    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STARTED);
   481	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: state callback returned id=%u\n", req->adv_id);
   482	    ret = BT_STATUS_SUCCESS;
   483	
   484	done:
   485	    if (req->adpt.start_adv.adv_data)
   486	        free(req->adpt.start_adv.adv_data);
   487	    if (req->adpt.start_adv.scan_rsp_data)
   488	        free(req->adpt.start_adv.scan_rsp_data);
   489	}
   490	
   491	bt_status_t bt_sal_le_start_adv(bt_controller_id_t id, uint8_t adv_id, ble_adv_params_t* params, uint8_t* adv_data, uint16_t adv_len, uint8_t* scan_rsp_data, uint16_t scan_rsp_len)
   492	{
   493	    sal_adapter_req_t* req;
   494	    int ret;
   495	    bool ext_adv;
   496	    bool ext_supported;
   497	
   498	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: request enter id=%u\n", adv_id);
   499	    req = sal_adapter_req(id, adv_id, STACK_CALL(start_adv));
   500	    if (!req) {
   501	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=request_alloc status=%d\n", BT_STATUS_NOMEM);
   502	        BT_LOGE("%s, req null", __func__);
   503	        return BT_STATUS_NOMEM;
   504	    }
   505	
   506	    ret = zblue_le_ext_convert_param(params, &req->adpt.start_adv.param);
   507	    if (ret) {
   508	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=convert status=%d\n", ret);
   509	        BT_LOGE("%s, le ext adv convert fail, err:%d", __func__, ret);
   510	        ret = BT_STATUS_PARM_INVALID;
   511	        goto error;
   512	    }
   513	
   514	    ext_supported = bt_le_ext_adv_is_supported();
   515	    ext_adv = (req->adpt.start_adv.param.options & BT_LE_ADV_OPT_EXT_ADV) ? true : false;
   516	
   517	    if (ext_adv && !ext_supported) {
   518	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=ext_unsupported status=%d\n", BT_STATUS_UNSUPPORTED);
   519	        BT_LOGE("%s, controller not support ext adv", __func__);
   520	        ret = BT_STATUS_UNSUPPORTED;
   521	        goto error;
   522	    }
   523	
   524	    if (((!(req->adpt.start_adv.param.options & BT_LE_ADV_OPT_SCANNABLE) && ext_adv)
   525	            || !ext_adv)
   526	        && adv_data && adv_len > 0) {
   527	        req->adpt.start_adv.adv_data = malloc(adv_len);
   528	        if (!req->adpt.start_adv.adv_data) {
   529	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=adv_copy status=%d\n", BT_STATUS_NOMEM);
   530	            BT_LOGE("%s, malloc fail", __func__);
   531	            ret = BT_STATUS_NOMEM;
   532	            goto error;
   533	        }
   534	
   535	        memcpy(req->adpt.start_adv.adv_data, adv_data, adv_len);
   536	        req->adpt.start_adv.adv_len = adv_len;
   537	    } else {
   538	        req->adpt.start_adv.adv_data = NULL;
   539	        req->adpt.start_adv.adv_len = 0;
   540	    }
   541	
   542	    if ((((req->adpt.start_adv.param.options & BT_LE_ADV_OPT_SCANNABLE) && ext_adv)
   543	            || !ext_adv)
   544	        && scan_rsp_data && scan_rsp_len > 0) {
   545	        req->adpt.start_adv.scan_rsp_data = malloc(scan_rsp_len);
   546	        if (!req->adpt.start_adv.scan_rsp_data) {
   547	            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=scan_rsp_copy status=%d\n", BT_STATUS_NOMEM);
   548	            BT_LOGE("%s, malloc fail", __func__);
   549	            ret = BT_STATUS_NOMEM;
   550	            goto error;
   551	        }
   552	
   553	        memcpy(req->adpt.start_adv.scan_rsp_data, scan_rsp_data, scan_rsp_len);
   554	        req->adpt.start_adv.scan_rsp_len = scan_rsp_len;
   555	    } else {
   556	        req->adpt.start_adv.scan_rsp_data = NULL;
   557	        req->adpt.start_adv.scan_rsp_len = 0;
   558	    }
   559	
   560	    if (params->duration) {
   561	        req->adpt.start_adv.ext_param.timeout = params->duration;
   562	    }
   563	
   564	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: service-loop post begin id=%u\n", adv_id);
   565	    ret = sal_send_req(req);
   566	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: service-loop post returned status=%d\n", ret);
   567	    return ret;
   568	
   569	error:
   570	    if (req->adpt.start_adv.adv_data)
   571	        free(req->adpt.start_adv.adv_data);
   572	    if (req->adpt.start_adv.scan_rsp_data)
   573	        free(req->adpt.start_adv.scan_rsp_data);
   574	    free(req);
   575	    return ret;
   576	}
