   578	static void STACK_CALL(stop_adv)(void* args)
   579	{
   580	    sal_adapter_req_t* req = args;
   581	    struct bt_le_adv_set* adv_set;
   582	    int ret;
   583	    bool ext_supported;
   584	
   585	    ext_supported = bt_le_ext_adv_is_supported();
   586	
   587	    if (!ext_supported) {
   588	        ret = bt_le_adv_stop();
   589	        if (ret) {
   590	            BT_LOGE("%s, legacy adv stop fail", __func__);
   591	            return;
   592	        } else {
   593	            goto stopped;
   594	        }
   595	    }
   596	
   597	    adv_set = zblue_le_ext_find_adv(req->adv_id);
   598	    if (!adv_set) {
   599	        BT_LOGE("%s, le ext adv_set find fail", __func__);
   600	        return;
   601	    }
   602	
   603	    ret = bt_le_ext_adv_stop(adv_set->adv);
   604	    if (ret) {
   605	        BT_LOGE("%s, le ext adv stop fail", __func__);
   606	        return;
   607	    }
   608	
   609	    ret = zblue_le_ext_delete(adv_set);
   610	    if (ret) {
   611	        BT_LOGE("%s, le ext adv stop fail", __func__);
   612	        return;
   613	    }
   614	
   615	stopped:
   616	    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STOPPED);
   617	}
