   412	static void service_after_work_cb(uv_work_t* req, int status)
   413	{
   414	    service_work_t* work = req->data;
   415	    assert(status == 0);
   416	    assert(work);
   417	
   418	    if (work->after_work_cb)
   419	        work->after_work_cb(work, work->userdata);
   420	    free(work);
   421	}
   422	
   423	service_work_t* service_loop_work(void* user_data, service_work_cb_t work_cb,
   424	    service_after_work_cb_t after_work_cb)
   425	{
   426	    uv_loop_t* handle = get_service_uv_loop();
   427	
   428	    service_work_t* work = zalloc(sizeof(*work));
   429	    if (work == NULL)
   430	        return work;
   431	
   432	    work->userdata = user_data;
   433	    work->work_cb = work_cb;
   434	    work->after_work_cb = after_work_cb;
