   406	static void STACK_CALL(start_adv)(void* args)
   407	{
   408	    sal_adapter_req_t* req = args;
   409	    struct bt_le_ext_adv* adv;
   410	    int ret;
   411	    struct bt_data ad[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   412	    struct bt_data sd[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   413	    size_t ad_size = 0;
   414	    size_t sd_size = 0;
   415	    bool ext_supported = bt_le_ext_adv_is_supported();
   416	
   417	    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: execute id=%u\n", req->adv_id);
   418	
   419	    ret = parse_bt_adv_data(req->adpt.start_adv.adv_data, req->adpt.start_adv.adv_len,
   420	        ad, ARRAY_SIZE(ad), &ad_size);
   421	    if (ret) {
   422	        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_adv status=%d\n", ret);
   423	        BT_LOGE("%s, parse adv_data fail, err:%d", __func__, ret);
   424	        goto done;
   425	    }
