   303	
   304	void mm_free(FAR struct mm_heap_s *heap, FAR void *mem)
   305	{
   306	  minfo("Freeing %p\n", mem);
   307	
   308	  /* Protect against attempts to free a NULL reference */
   309	
   310	  if (mem == NULL)
   311	    {
   312	      return;
   313	    }
   314	
   315	  DEBUGASSERT(mm_heapmember(heap, mem));
   316	
   317	#if CONFIG_MM_FREE_DELAYCOUNT_MAX > 0
   318	  add_delaylist(heap, mem, true);
   319	#else
   320	
   321	  mm_forcefree(heap, mem);
   322	#endif
   323	}
