    41	/****************************************************************************
    42	 * Name: mm_heapmember
    43	 *
    44	 * Description:
    45	 *   Check if an address lies in the heap.
    46	 *
    47	 * Parameters:
    48	 *   heap - The heap to check
    49	 *   mem  - The address to check
    50	 *
    51	 * Return Value:
    52	 *   true if the address is a member of the heap.  false if not
    53	 *   not.  If the address is not a member of the heap, then it
    54	 *   must be a member of the user-space heap (unchecked)
    55	 *
    56	 ****************************************************************************/
    57	
    58	bool mm_heapmember(FAR struct mm_heap_s *heap, FAR void *mem)
    59	{
    60	  mem = kasan_clear_tag(mem);
    61	#if CONFIG_MM_REGIONS > 1
    62	  int i;
    63	
    64	  /* A valid address from the heap for this region would have to lie
    65	   * between the region's two guard nodes.
    66	   */
    67	
    68	  for (i = 0; i < heap->mm_nregions; i++)
    69	    {
    70	      if (mem > kasan_clear_tag((FAR void *)heap->mm_heapstart[i]) &&
    71	          mem < kasan_clear_tag((FAR void *)heap->mm_heapend[i]))
    72	        {
    73	          return true;
    74	        }
    75	    }
    76	
    77	  /* The address does not like any any region assigned to the heap */
    78	
    79	  return false;
    80	
    81	#else
    82	  /* A valid address from the heap would have to lie between the
    83	   * two guard nodes.
    84	   */
    85	
    86	  if (mem > kasan_clear_tag((FAR void *)heap->mm_heapstart[0]) &&
    87	      mem < kasan_clear_tag((FAR void *)heap->mm_heapend[0]))
    88	    {
    89	      return true;
    90	    }
    91	
    92	  /* Otherwise, the address does not lie in the heap */
    93	
    94	  return false;
    95	
    96	#endif
    97	}
