   144	static bool hci_cmd_is_quarantined(struct bt_dev *hdev)
   145	{
   146		struct hci_cmd_quarantine *quarantine = &cmd_quarantine[hdev->dev_id];
   147		k_spinlock_key_t key;
   148		bool failed;
   149	
   150		key = k_spin_lock(&quarantine->lock);
   151		failed = quarantine->failed;
   152		k_spin_unlock(&quarantine->lock, key);
   153	
   154		return failed;
   155	}
