  1837	int bt_le_ext_adv_start(struct bt_le_ext_adv *adv,
  1838				const struct bt_le_ext_adv_start_param *param)
  1839	{
  1840		struct bt_conn *conn = NULL;
  1841		int err;
  1842	
  1843		if (bt_le_adv_uses_legacy_hci(adv)) {
  1844			return 0;
  1845		}
  1846	
  1847		if (atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
  1848			return -EALREADY;
  1849		}
  1850	
  1851		if (IS_ENABLED(CONFIG_BT_PERIPHERAL) &&
  1852		    atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
  1853			err = le_adv_start_add_conn(adv, &conn);
  1854			if (err) {
  1855				return err;
  1856			}
  1857		}
  1858	
  1859		atomic_set_bit_to(adv->flags, BT_ADV_LIMITED, param &&
  1860				  (param->timeout > 0 || param->num_events > 0));
  1861	
  1862		if (atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
  1863			if (IS_ENABLED(CONFIG_BT_PRIVACY) &&
  1864			    !atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
  1865				bt_id_set_adv_private_addr(adv);
  1866			}
  1867		} else {
  1868			if (!atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
  1869				bt_id_set_adv_private_addr(adv);
  1870			}
  1871		}
  1872	
  1873		if (get_adv_name_type(adv) != ADV_NAME_TYPE_NONE &&
  1874		    !atomic_test_bit(adv->flags, BT_ADV_DATA_SET)) {
  1875			/* Set the advertiser name */
  1876			bt_le_ext_adv_set_data(adv, NULL, 0, NULL, 0);
  1877		}
  1878	
  1879		err = bt_le_adv_set_enable_ext(adv, true, param);
  1880		if (err) {
  1881			LOG_ERR("Failed to start advertiser");
  1882			if (IS_ENABLED(CONFIG_BT_PERIPHERAL) && conn) {
  1883				bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
  1884				bt_conn_unref(conn);
  1885			}
  1886	
  1887			return err;
  1888		}
  1889	
  1890		if (IS_ENABLED(CONFIG_BT_PERIPHERAL) && conn) {
  1891			/* If undirected connectable advertiser we have created a
  1892			 * connection object that we don't yet give to the application.
  1893			 * Since we don't give the application a reference to manage in
  1894			 * this case, we need to release this reference here
  1895			 */
  1896			bt_conn_unref(conn);
  1897		}
  1898	
  1899		return 0;
  1900	}
