  3291	static void hci_core_send_cmd(struct bt_dev *hdev)
  3292	{
  3293		struct hci_cmd_quarantine *quarantine = &cmd_quarantine[hdev->dev_id];
  3294		struct net_buf *old;
  3295		struct net_buf *buf;
  3296		k_spinlock_key_t key;
  3297		int err;
  3298	
  3299		/* Get next command */
  3300		LOG_DBG("dev:%d, fetch cmd", hdev->dev_id);
  3301		key = k_spin_lock(&quarantine->lock);
  3302		if (quarantine->failed) {
  3303			k_spin_unlock(&quarantine->lock, key);
  3304			hci_cmd_fail_queued(hdev);
  3305			return;
  3306		}
  3307	
  3308		buf = k_fifo_get(&hdev->cmd_tx_queue, K_NO_WAIT);
  3309		BT_ASSERT(buf);
  3310	
  3311		old = atomic_ptr_set((atomic_ptr_t *)&hdev->sent_cmd, net_buf_ref(buf));
  3312		k_spin_unlock(&quarantine->lock, key);
  3313	
  3314		/* Clear out any unexpected existing sent command */
  3315		if (old) {
  3316			LOG_ERR("Uncleared pending sent_cmd");
  3317			net_buf_unref(old);
  3318		}
  3319	
  3320		LOG_DBG("Sending command 0x%04x %s (buf %p) to driver", cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode), buf);
  3321	
  3322		err = bt_send(hdev, buf);
  3323		if (err) {
  3324			LOG_ERR("Unable to send to driver (err %d)", err);
  3325			if (!hci_cmd_is_quarantined(hdev)) {
  3326				k_sem_give(&hdev->ncmd_sem);
  3327			}
  3328			hci_cmd_done(hdev, cmd(buf)->opcode, BT_HCI_ERR_UNSPECIFIED, buf);
  3329			net_buf_unref(buf);
  3330			bt_tx_irq_raise(hdev);
  3331		}
  3332	}
