  1879		err = bt_le_adv_set_enable_ext(adv, true, param);
  1880		if (err) {
  1881			LOG_ERR("Failed to start advertiser");
  1882			if (IS_ENABLED(CONFIG_BT_PERIPHERAL) && conn) {
  1883				bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
  1884				bt_conn_unref(conn);
  1885			}
  1886	
  1887			return err;
  1888		}
  1889	
  1890		if (IS_ENABLED(CONFIG_BT_PERIPHERAL) && conn) {
  1891			/* If undirected connectable advertiser we have created a
