  1853			err = le_adv_start_add_conn(adv, &conn);
  1854			if (err) {
  1855				return err;
  1856			}
  1857		}
  1858	
  1859		atomic_set_bit_to(adv->flags, BT_ADV_LIMITED, param &&
  1860				  (param->timeout > 0 || param->num_events > 0));
  1861	
  1862		if (atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
  1863			if (IS_ENABLED(CONFIG_BT_PRIVACY) &&
  1864			    !atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
  1865				bt_id_set_adv_private_addr(adv);
  1866			}
  1867		} else {
  1868			if (!atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
  1869				bt_id_set_adv_private_addr(adv);
  1870			}
  1871		}
  1872	
  1873		if (get_adv_name_type(adv) != ADV_NAME_TYPE_NONE &&
  1874		    !atomic_test_bit(adv->flags, BT_ADV_DATA_SET)) {
  1875			/* Set the advertiser name */
  1876			bt_le_ext_adv_set_data(adv, NULL, 0, NULL, 0);
  1877		}
