   174	static void hci_cmd_clear_quarantine(struct bt_dev *hdev)
   175	{
   176		struct hci_cmd_quarantine *quarantine = &cmd_quarantine[hdev->dev_id];
   177		k_spinlock_key_t key;
   178	
   179		key = k_spin_lock(&quarantine->lock);
   180		quarantine->failed = false;
   181		k_spin_unlock(&quarantine->lock, key);
