    64	  /* A valid address from the heap for this region would have to lie
    65	   * between the region's two guard nodes.
    66	   */
    67	
    68	  for (i = 0; i < heap->mm_nregions; i++)
    69	    {
    70	      if (mem > kasan_clear_tag((FAR void *)heap->mm_heapstart[i]) &&
    71	          mem < kasan_clear_tag((FAR void *)heap->mm_heapend[i]))
    72	        {
    73	          return true;
    74	        }
    75	    }
    76	
    77	  /* The address does not like any any region assigned to the heap */
    78	
    79	  return false;
    80	
    81	#else
    82	  /* A valid address from the heap would have to lie between the
    83	   * two guard nodes.
    84	   */
    85	
    86	  if (mem > kasan_clear_tag((FAR void *)heap->mm_heapstart[0]) &&
    87	      mem < kasan_clear_tag((FAR void *)heap->mm_heapend[0]))
    88	    {
    89	      return true;
    90	    }
    91	
    92	  /* Otherwise, the address does not lie in the heap */
    93	
    94	  return false;
    95	
    96	#endif
