  1965			if (err) {
  1966				return err;
  1967			}
  1968		}
  1969	
  1970		ext_adv = atomic_test_bit(adv->flags, BT_ADV_EXT_ADV);
  1971		scannable = atomic_test_bit(adv->flags, BT_ADV_SCANNABLE);
