   157	static int hci_cmd_enqueue(struct bt_dev *hdev, struct net_buf *buf)
   158	{
   159		struct hci_cmd_quarantine *quarantine = &cmd_quarantine[hdev->dev_id];
   160		k_spinlock_key_t key;
   161	
   162		key = k_spin_lock(&quarantine->lock);
   163		if (quarantine->failed) {
   164			k_spin_unlock(&quarantine->lock, key);
   165			return -EIO;
   166		}
   167	
   168		k_fifo_put(&hdev->cmd_tx_queue, buf);
   169		k_spin_unlock(&quarantine->lock, key);
   170	
   171		return 0;
   172	}
