  2619	static void hci_cmd_finish(struct net_buf *buf, uint8_t status)
  2620	{
  2621		if (cmd(buf)->state && !status) {
  2622			struct bt_hci_cmd_state_set *update = cmd(buf)->state;
  2623	
  2624			atomic_set_bit_to(update->target, update->bit, update->val);
  2625		}
  2626	
  2627		if (cmd(buf)->sync) {
  2628			LOG_DBG("sync cmd released");
  2629			cmd(buf)->status = status;
  2630			k_sem_give(cmd(buf)->sync);
  2631		}
  2632	
  2633		net_buf_unref(buf);
  2634	}
  2635	
  2636	static void hci_cmd_fail_queued(struct bt_dev *hdev)
  2637	{
  2638		struct net_buf *buf;
  2639	
  2640		while ((buf = k_fifo_get(&hdev->cmd_tx_queue, K_NO_WAIT)) != NULL) {
  2641			hci_cmd_finish(buf, BT_HCI_ERR_HW_FAILURE);
  2642		}
  2643	}
  2644	
  2645	static void hci_cmd_quarantine_controller(struct bt_dev *hdev)
  2646	{
  2647		struct hci_cmd_quarantine *quarantine = &cmd_quarantine[hdev->dev_id];
  2648		struct net_buf *buf;
  2649		k_spinlock_key_t key;
  2650	
  2651		key = k_spin_lock(&quarantine->lock);
  2652		quarantine->failed = true;
  2653		buf = (struct net_buf *)atomic_ptr_clear((atomic_ptr_t *)&hdev->sent_cmd);
  2654		k_spin_unlock(&quarantine->lock, key);
  2655	
  2656		if (buf) {
  2657			LOG_ERR("Terminating pending HCI opcode=0x%04x", cmd(buf)->opcode);
  2658			hci_cmd_finish(buf, BT_HCI_ERR_HW_FAILURE);
  2659		}
  2660	
  2661		hci_cmd_fail_queued(hdev);
  2662	
  2663		LOG_ERR("HCI controller quarantined");
  2664	}
  2665	
  2666	static void hci_cmd_done(struct bt_dev *hdev, uint16_t opcode,
  2667				 uint8_t status, struct net_buf *evt_buf)
  2668	{
  2669		/* Original command buffer. */
  2670		struct net_buf *buf = NULL;
  2671	
  2672		LOG_DBG("opcode 0x%04x %s, status 0x%02x %s buf %p", opcode,
  2673			bt_hci_opcode_to_str(opcode),
  2674			status, bt_hci_err_to_str(status), evt_buf);
  2675	
  2676		/* Unsolicited cmd complete. This does not complete a command.
  2677		 * The controller can send these for effect of the `ncmd` field.
  2678		 */
  2679		if (opcode == 0) {
  2680			goto exit;
  2681		}
  2682	
  2683		/* Take the original command buffer reference. */
  2684		buf = (struct net_buf *)atomic_ptr_clear((atomic_ptr_t *)&hdev->sent_cmd);
  2685	
  2686		if (!buf) {
  2687			LOG_ERR("No command sent for cmd complete 0x%04x", opcode);
  2688			goto exit;
  2689		}
  2690	
  2691		if (cmd(buf)->opcode != opcode) {
  2692			LOG_ERR("OpCode 0x%04x %s completed instead of expected 0x%04x %s", opcode,
  2693				bt_hci_opcode_to_str(opcode), cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode));
  2694			buf = atomic_ptr_set((atomic_ptr_t *)&hdev->sent_cmd, buf);
  2695			__ASSERT_NO_MSG(!buf);
  2696			goto exit;
  2697		}
  2698	
  2699		/* Response data is to be delivered in the original command
  2700		 * buffer.
  2701		 */
  2702		if (evt_buf != buf) {
  2703			net_buf_reset(buf);
  2704			bt_buf_set_type(buf, BT_BUF_EVT);
  2705			net_buf_reserve(buf, BT_BUF_RESERVE);
  2706			net_buf_add_mem(buf, evt_buf->data, evt_buf->len);
  2707		}
  2708	
  2709	exit:
  2710		if (buf) {
  2711			hci_cmd_finish(buf, status);
  2712		}
  2713	}
  2714	
  2715	static void hci_cmd_complete(struct bt_dev *hdev, struct net_buf *buf)
  2716	{
  2717		struct bt_hci_evt_cmd_complete *evt;
  2718		uint8_t status, ncmd;
  2719		uint16_t opcode;
  2720	
  2721		evt = net_buf_pull_mem(buf, sizeof(*evt));
  2722		ncmd = evt->ncmd;
  2723		opcode = sys_le16_to_cpu(evt->opcode);
  2724	
  2725		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
  2726		if (hci_cmd_is_quarantined(hdev)) {
  2727			LOG_ERR("Ignoring late HCI command complete opcode=0x%04x while quarantined",
  2728				opcode);
  2729			return;
  2730		}
  2731	
  2732		/* All command return parameters have a 1-byte status in the
  2733		 * beginning, so we can safely make this generalization.
  2734		 */
  2735		status = buf->data[0];
  2736	
  2737		/* HOST_NUM_COMPLETED_PACKETS should not generate a response under normal operation.
  2738		 * The generation of this command ignores `ncmd_sem`, so should not be given here.
  2739		 */
  2740		if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
  2741			LOG_WRN("Unexpected HOST_NUM_COMPLETED_PACKETS, status 0x%02x %s",
  2742				status, bt_hci_err_to_str(status));
  2743			return;
  2744		}
  2745	
  2746		hci_cmd_done(hdev, opcode, status, buf);
  2747	
  2748		/* Allow next command to be sent */
  2749		if (ncmd && !hci_cmd_is_quarantined(hdev)) {
  2750			k_sem_give(&hdev->ncmd_sem);
  2751			bt_tx_irq_raise(hdev);
  2752		}
  2753	}
