  2759		uint8_t ncmd;
  2760	
  2761		evt = net_buf_pull_mem(buf, sizeof(*evt));
  2762		opcode = sys_le16_to_cpu(evt->opcode);
  2763		ncmd = evt->ncmd;
  2764	
  2765		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
  2766		if (hci_cmd_is_quarantined(hdev)) {
  2767			LOG_ERR("Ignoring late HCI command status opcode=0x%04x while quarantined",
  2768				opcode);
