  3250	static inline uint8_t bt_hci_evt_get_flags(uint8_t evt)
  3251	{
  3252		switch (evt) {
  3253		case BT_HCI_EVT_DISCONN_COMPLETE:
  3254			return BT_HCI_EVT_FLAG_RECV | BT_HCI_EVT_FLAG_RECV_PRIO;
  3255			/* fallthrough */
  3256	#if defined(CONFIG_BT_CONN) || defined(CONFIG_BT_ISO)
  3257		case BT_HCI_EVT_NUM_COMPLETED_PACKETS:
  3258	#if defined(CONFIG_BT_CONN)
  3259		case BT_HCI_EVT_DATA_BUF_OVERFLOW:
  3260			__fallthrough;
  3261	#endif /* defined(CONFIG_BT_CONN) */
  3262	#endif /* CONFIG_BT_CONN ||  CONFIG_BT_ISO */
  3263		case BT_HCI_EVT_CMD_COMPLETE:
  3264		case BT_HCI_EVT_CMD_STATUS:
  3265		case BT_HCI_EVT_HARDWARE_ERROR:
  3266			return BT_HCI_EVT_FLAG_RECV_PRIO;
  3267		default:
  3268			return BT_HCI_EVT_FLAG_RECV;
  3269		}
  3270	}
