+
+static int hci_cmd_enqueue(struct bt_dev *hdev, struct net_buf *buf)
+{
+	struct hci_cmd_quarantine *quarantine = &cmd_quarantine[hdev->dev_id];
+	k_spinlock_key_t key;
+
+	key = k_spin_lock(&quarantine->lock);
+	if (quarantine->failed) {
+		k_spin_unlock(&quarantine->lock, key);
+		return -EIO;
+	}
+
+	k_fifo_put(&hdev->cmd_tx_queue, buf);
+	k_spin_unlock(&quarantine->lock, key);
+
+	return 0;
+}
