  1534	int bt_le_adv_stop_mc(uint8_t dev_id)
  1535	{
  1536		struct bt_le_ext_adv *adv;
  1537		struct bt_dev *hdev;
  1538		int err;
  1539	
  1540		hdev = bt_dev_get(dev_id);
  1541		if (!hdev) {
  1542			return -ENODEV;
  1543		}
  1544	
  1545		adv = bt_le_adv_lookup_legacy(hdev);
  1546		if (!adv) {
  1547			LOG_ERR("No valid legacy adv");
  1548			return 0;
  1549		}
  1550	
  1551		(void)bt_le_lim_adv_cancel_timeout(adv);
  1552	
  1553		/* Make sure advertising is not re-enabled later even if it's not
  1554		 * currently enabled (i.e. BT_DEV_ADVERTISING is not set).
  1555		 */
  1556		atomic_clear_bit(adv->flags, BT_ADV_PERSIST);
  1557	
  1558		if (!atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
  1559			/* Legacy advertiser exists, but is not currently advertising.
  1560			 * This happens when keep advertising behavior is active but
  1561			 * no conn object is available to do connectable advertising.
  1562			 */
  1563			bt_le_adv_delete_legacy(hdev);
  1564			return 0;
  1565		}
  1566	
  1567		if (IS_ENABLED(CONFIG_BT_PERIPHERAL) &&
  1568		    atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
  1569			le_adv_stop_free_conn(adv, 0);
  1570		}
  1571	
  1572		if (IS_ENABLED(CONFIG_BT_EXT_ADV) &&
  1573		    BT_DEV_FEAT_LE_EXT_ADV(hdev->le.features)) {
  1574			err = bt_le_adv_set_enable_ext(adv, false, NULL);
  1575			if (err) {
  1576				return err;
  1577			}
  1578		} else {
  1579			err = bt_le_adv_set_enable_legacy(adv, false);
  1580			if (err) {
  1581				return err;
  1582			}
  1583		}
  1584	
  1585		bt_le_adv_delete_legacy(hdev);
  1586	
  1587	#if defined(CONFIG_BT_OBSERVER)
  1588		if (!(IS_ENABLED(CONFIG_BT_EXT_ADV) &&
  1589		      BT_DEV_FEAT_LE_EXT_ADV(hdev->le.features)) &&
  1590		    !IS_ENABLED(CONFIG_BT_PRIVACY) &&
  1591		    !IS_ENABLED(CONFIG_BT_SCAN_WITH_IDENTITY)) {
  1592			/* If scan is ongoing set back NRPA */
  1593			if (atomic_test_bit(hdev->flags, BT_DEV_SCANNING)) {
  1594				bt_le_scan_set_enable(hdev, BT_HCI_LE_SCAN_DISABLE);
  1595				bt_id_set_private_addr(hdev, BT_ID_DEFAULT);
  1596				bt_le_scan_set_enable(hdev, BT_HCI_LE_SCAN_ENABLE);
  1597			}
  1598		}
  1599	#endif /* defined(CONFIG_BT_OBSERVER) */
  1600	
  1601		return 0;
  1602	}
