1250	static int le_ext_adv_param_set(struct bt_le_ext_adv *adv,
1251					const struct bt_le_adv_param *param,
1252					bool  has_scan_data)
1253	{
1254		struct bt_hci_cp_le_set_ext_adv_param *cp;
1255		bool dir_adv = param->peer != NULL, scannable;
1256		struct net_buf *buf, *rsp;
1257		int err;
1258		enum adv_name_type name_type;
1259		uint16_t props = 0;
1260	
1261		buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_EXT_ADV_PARAM, sizeof(*cp));
1262		if (!buf) {
1263			return -ENOBUFS;
1264		}
1265	
1266		cp = net_buf_add(buf, sizeof(*cp));
1267		(void)memset(cp, 0, sizeof(*cp));
1268	
1269		adv->options = param->options;
1270	
1271		err = bt_id_set_adv_own_addr(adv, param->options, dir_adv,
1272					     &cp->own_addr_type);
1273		if (err) {
1274			net_buf_unref(buf);
1275			return err;
1276		}
1277	
1278		if (dir_adv) {
1279			bt_addr_le_copy(&adv->target_addr, param->peer);
1280		} else {
1281			bt_addr_le_copy(&adv->target_addr, BT_ADDR_LE_ANY);
1282		}
1283	
1284		name_type = get_adv_name_type_param(param);
1285	
1286		cp->handle = adv->handle;
1287		sys_put_le24(param->interval_min, cp->prim_min_interval);
1288		sys_put_le24(param->interval_max, cp->prim_max_interval);
1289		cp->prim_channel_map = get_adv_channel_map(param->options);
1290		cp->filter_policy = get_filter_policy(param->options);
1291		cp->tx_power = BT_HCI_LE_ADV_TX_POWER_NO_PREF;
1292	
1293		cp->prim_adv_phy = BT_HCI_LE_PHY_1M;
1294		if ((param->options & BT_LE_ADV_OPT_EXT_ADV) &&
1295		    !(param->options & BT_LE_ADV_OPT_NO_2M)) {
1296			cp->sec_adv_phy = BT_HCI_LE_PHY_2M;
1297		} else {
1298			cp->sec_adv_phy = BT_HCI_LE_PHY_1M;
1299		}
1300	
1301		if (param->options & BT_LE_ADV_OPT_CODED) {
1302			cp->prim_adv_phy = BT_HCI_LE_PHY_CODED;
1303			cp->sec_adv_phy = BT_HCI_LE_PHY_CODED;
1304		}
1305	
1306		if (!(param->options & BT_LE_ADV_OPT_EXT_ADV)) {
1307			props |= BT_HCI_LE_ADV_PROP_LEGACY;
1308		}
1309	
1310		if (param->options & BT_LE_ADV_OPT_USE_TX_POWER) {
1311			props |= BT_HCI_LE_ADV_PROP_TX_POWER;
1312		}
1313	
1314		if (param->options & BT_LE_ADV_OPT_ANONYMOUS) {
1315			props |= BT_HCI_LE_ADV_PROP_ANON;
1316		}
1317	
1318		if (param->options & BT_LE_ADV_OPT_NOTIFY_SCAN_REQ) {
1319			cp->scan_req_notify_enable = BT_HCI_LE_ADV_SCAN_REQ_ENABLE;
1320		}
1321	
1322		if (param->options & _BT_LE_ADV_OPT_CONNECTABLE) {
1323			props |= BT_HCI_LE_ADV_PROP_CONN;
1324			if (!dir_adv && !(param->options & BT_LE_ADV_OPT_EXT_ADV)) {
1325				/* When using non-extended adv packets then undirected
1326				 * advertising has to be scannable as well.
1327				 * We didn't require this option to be set before, so
1328				 * it is implicitly set instead in this case.
1329				 */
1330				props |= BT_HCI_LE_ADV_PROP_SCAN;
1331			}
1332		}
1333	
1334		if ((param->options & BT_LE_ADV_OPT_SCANNABLE) || has_scan_data ||
1335		    (name_type == ADV_NAME_TYPE_SD)) {
1336			props |= BT_HCI_LE_ADV_PROP_SCAN;
1337		}
1338	
1339		scannable = !!(props & BT_HCI_LE_ADV_PROP_SCAN);
1340	
1341		if (dir_adv) {
1342			props |= BT_HCI_LE_ADV_PROP_DIRECT;
1343			if (!(param->options & BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY)) {
1344				props |= BT_HCI_LE_ADV_PROP_HI_DC_CONN;
1345			}
1346	
1347			bt_addr_le_copy(&cp->peer_addr, param->peer);
1348		}
1349	
1350		cp->sid = param->sid;
1351	
1352		cp->sec_adv_max_skip = param->secondary_max_skip;
1353	
1354		cp->props = sys_cpu_to_le16(props);
1355		err = bt_hci_cmd_send_sync(adv->hdev, BT_HCI_OP_LE_SET_EXT_ADV_PARAM, buf, &rsp);
1356		if (err) {
1357			return err;
1358		}
1359	
1360	#if defined(CONFIG_BT_EXT_ADV)
1361		struct bt_hci_rp_le_set_ext_adv_param *rp = (void *)rsp->data;
1362	
1363		adv->tx_power = rp->tx_power;
1364	#endif /* defined(CONFIG_BT_EXT_ADV) */
1365	
1366		net_buf_unref(rsp);
1367	
1368		atomic_set_bit(adv->flags, BT_ADV_PARAMS_SET);
1369	
1370		if (atomic_test_and_clear_bit(adv->flags, BT_ADV_RANDOM_ADDR_PENDING)) {
1371			err = bt_id_set_adv_random_addr(adv, &adv->random_addr.a);
1372			if (err) {
1373				return err;
1374			}
1375		}
1376	
1377		/* Flag only used by bt_le_adv_start API. */
1378		atomic_set_bit_to(adv->flags, BT_ADV_PERSIST, false);
1379	
1380		atomic_set_bit_to(adv->flags, BT_ADV_INCLUDE_NAME_AD,
1381				  name_type == ADV_NAME_TYPE_AD);
1382	
1383		atomic_set_bit_to(adv->flags, BT_ADV_INCLUDE_NAME_SD,
1384				  name_type == ADV_NAME_TYPE_SD);
1385	
1386		atomic_set_bit_to(adv->flags, BT_ADV_CONNECTABLE,
1387				  param->options & _BT_LE_ADV_OPT_CONNECTABLE);
1388	
1389		atomic_set_bit_to(adv->flags, BT_ADV_SCANNABLE, scannable);
