   349	void bt_send_one_host_num_completed_packets(struct bt_dev *hdev, uint16_t handle)
   350	{
   351		if (!IS_ENABLED(CONFIG_BT_HCI_ACL_FLOW_CONTROL)) {
   352			ARG_UNUSED(hdev);
   353			ARG_UNUSED(handle);
   354			return;
   355		}
   356	
   357		struct bt_hci_cp_host_num_completed_packets *cp;
   358		struct bt_hci_handle_count *hc;
   359		struct net_buf *buf;
   360		int err;
   361	
   362		LOG_DBG("Reporting completed packet for handle %u", handle);
   363	
   364		buf = bt_hci_cmd_create(BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS,
   365					sizeof(*cp) + sizeof(*hc));
   366		BT_ASSERT_MSG(buf, "Unable to alloc for Host NCP");
   367	
   368		cp = net_buf_add(buf, sizeof(*cp));
   369		cp->num_handles = sys_cpu_to_le16(1);
   370	
   371		hc = net_buf_add(buf, sizeof(*hc));
   372		hc->handle = sys_cpu_to_le16(handle);
   373		hc->count  = sys_cpu_to_le16(1);
   374	
   375		err = bt_hci_cmd_send(hdev, BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS, buf);
   376		BT_ASSERT_MSG(err == 0, "Unable to send Host NCP (err %d)", err);
   377	}
