  4346	void hci_event_prio(struct bt_dev *hdev, struct net_buf *buf)
  4347	{
  4348		struct net_buf_simple_state state;
  4349		struct bt_hci_evt_hdr *hdr;
  4350		uint8_t evt_flags;
  4351	
  4352		net_buf_simple_save(&buf->b, &state);
  4353	
  4354		if (buf->len < sizeof(*hdr)) {
  4355			LOG_ERR("Invalid HCI event size (%u)", buf->len);
  4356			net_buf_unref(buf);
  4357			return;
  4358		}
  4359	
  4360		hdr = net_buf_pull_mem(buf, sizeof(*hdr));
  4361		evt_flags = bt_hci_evt_get_flags(hdr->evt);
  4362		BT_ASSERT(evt_flags & BT_HCI_EVT_FLAG_RECV_PRIO);
  4363	
  4364		handle_event(hdev, hdr->evt, buf, prio_events, ARRAY_SIZE(prio_events));
  4365	
  4366		if (evt_flags & BT_HCI_EVT_FLAG_RECV) {
  4367			net_buf_simple_restore(&buf->b, &state);
  4368		} else {
  4369			net_buf_unref(buf);
  4370		}
