  2715	static void hci_cmd_complete(struct bt_dev *hdev, struct net_buf *buf)
  2716	{
  2717		struct bt_hci_evt_cmd_complete *evt;
  2718		uint8_t status, ncmd;
  2719		uint16_t opcode;
  2720	
  2721		evt = net_buf_pull_mem(buf, sizeof(*evt));
  2722		ncmd = evt->ncmd;
  2723		opcode = sys_le16_to_cpu(evt->opcode);
  2724	
  2725		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
  2726		if (hci_cmd_is_quarantined(hdev)) {
  2727			LOG_ERR("Ignoring late HCI command complete opcode=0x%04x while quarantined",
  2728				opcode);
  2729			return;
  2730		}
  2731	
  2732		/* All command return parameters have a 1-byte status in the
  2733		 * beginning, so we can safely make this generalization.
  2734		 */
  2735		status = buf->data[0];
  2736	
  2737		/* HOST_NUM_COMPLETED_PACKETS should not generate a response under normal operation.
  2738		 * The generation of this command ignores `ncmd_sem`, so should not be given here.
  2739		 */
  2740		if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
  2741			LOG_WRN("Unexpected HOST_NUM_COMPLETED_PACKETS, status 0x%02x %s",
  2742				status, bt_hci_err_to_str(status));
  2743			return;
  2744		}
  2745	
  2746		hci_cmd_done(hdev, opcode, status, buf);
  2747	
  2748		/* Allow next command to be sent */
  2749		if (ncmd && !hci_cmd_is_quarantined(hdev)) {
  2750			k_sem_give(&hdev->ncmd_sem);
  2751			bt_tx_irq_raise(hdev);
  2752		}
  2753	}
