  4349		struct bt_hci_evt_hdr *hdr;
  4350		uint8_t evt_flags;
  4351	
  4352		net_buf_simple_save(&buf->b, &state);
  4353	
  4354		if (buf->len < sizeof(*hdr)) {
  4355			LOG_ERR("Invalid HCI event size (%u)", buf->len);
  4356			net_buf_unref(buf);
