   279	struct event_handler {
   280		uint8_t event;
   281		uint8_t min_len;
   282		void (*handler)(struct bt_dev *hdev, struct net_buf *buf);
   283	};
   284	
   285	#define EVENT_HANDLER(_evt, _handler, _min_len) \
   286	{ \
   287		.event = _evt, \
   288		.handler = _handler, \
   289		.min_len = _min_len, \
   290	}
   291	
   292	static int handle_event_common(struct bt_dev *hdev, uint8_t event, struct net_buf *buf,
   293				       const struct event_handler *handlers, size_t num_handlers)
   294	{
   295		size_t i;
   296	
   297		for (i = 0; i < num_handlers; i++) {
   298			const struct event_handler *handler = &handlers[i];
   299	
   300			if (handler->event != event) {
   301				continue;
   302			}
   303	
   304			if (buf->len < handler->min_len) {
   305				LOG_ERR("Too small (%u bytes) event 0x%02x", buf->len, event);
   306				return -EINVAL;
   307			}
   308	
   309			handler->handler(hdev, buf);
   310			return 0;
   311		}
   312	
   313		return -EOPNOTSUPP;
   314	}
   315	
   316	static void handle_event(struct bt_dev *hdev, uint8_t event, struct net_buf *buf,
   317				 const struct event_handler *handlers, size_t num_handlers)
   318	{
   319		int err;
   320	
   321		err = handle_event_common(hdev, event, buf, handlers, num_handlers);
   322		if (err == -EOPNOTSUPP) {
   323			LOG_WRN("Unhandled event 0x%02x len %u: %s", event, buf->len,
   324				bt_hex(buf->data, buf->len));
   325		}
   326	
   327		/* Other possible errors are handled by handle_event_common function */
   328	}
