   263	static struct bt_le_ext_adv *adv_new(struct bt_dev *hdev)
   264	{
   265		struct bt_le_ext_adv *adv = NULL;
   266		int i;
   267	
   268		for (i = 0; i < ARRAY_SIZE(hdev->adv_pool); i++) {
   269			if (!atomic_test_bit(hdev->adv_pool[i].flags, BT_ADV_CREATED)) {
   270				adv = &hdev->adv_pool[i];
   271				break;
   272			}
   273		}
   274	
   275		if (!adv) {
   276			return NULL;
   277		}
   278	
   279		(void)memset(adv, 0, sizeof(*adv));
   280		atomic_set_bit(hdev->adv_pool[i].flags, BT_ADV_CREATED);
   281		adv->handle = i;
   282	
   283		return adv;
   284	}
