        req->adpt.start_adv.scan_rsp_data,
        (size_t)req->adpt.start_adv.scan_rsp_len);

    ret = parse_bt_adv_data(req->adpt.start_adv.adv_data, req->adpt.start_adv.adv_len,
        ad, ARRAY_SIZE(ad), &ad_size);
    if (ret) {
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_adv status=%d\n", ret);
        BT_LOGE("%s, parse adv_data fail, err:%d", __func__, ret);
