static bt_status_t zblue_le_ext_create(struct bt_le_adv_param* param, struct bt_le_ext_adv** adv, uint8_t adv_id)
{
    int ret;
    uint8_t index;
    struct bt_le_adv_set* adv_set;

    ret = bt_le_ext_adv_create(param, &g_adv_cb, adv);
    if (ret) {
        BT_LOGE("%s, le ext adv create fail, err:%d", __func__, ret);
        return BT_STATUS_FAIL;
    }

    index = bt_le_ext_adv_get_index(*adv);
    adv_set = malloc(sizeof(*adv_set));
    if (!adv_set) {
        BT_LOGE("%s, malloc fail", __func__);
        bt_le_ext_adv_delete(*adv);
        return BT_STATUS_NOMEM;
    }

    adv_set->adv = *adv;
    adv_set->adv_id = adv_id;
    adv_set->delete_pending = false;
    g_adv_sets[index] = adv_set;

    return BT_STATUS_SUCCESS;
}

static bt_status_t zblue_le_ext_delete(struct bt_le_adv_set* adv_set)
{
    int ret;
    uint8_t index;

    if (!adv_set) {
        BT_LOGE("%s, adv set null", __func__);
        return BT_STATUS_PARM_INVALID;
    }

    ret = bt_le_ext_adv_delete(adv_set->adv);
    if (ret) {
        BT_LOGE("%s, le ext adv delet fail, err:%d", __func__, ret);
        return BT_STATUS_FAIL;
    }

    index = bt_le_ext_adv_get_index(adv_set->adv);
    free(adv_set);
    g_adv_sets[index] = NULL;

    return BT_STATUS_SUCCESS;
}

static void STACK_CALL(cleanup_terminated_adv)(void* args)
{
    sal_adapter_req_t* req = args;
    struct bt_le_adv_set* adv_set;

    adv_set = zblue_le_ext_find_adv(req->adv_id);
    if (!adv_set || !adv_set->delete_pending) {
        return;
    }

    BT_LOGD("sal adv: cleanup terminated id=%u", req->adv_id);
    if (zblue_le_ext_delete(adv_set) != BT_STATUS_SUCCESS) {
        adv_set->delete_pending = false;
        return;
    }

    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STOPPED);
}

static struct bt_le_adv_set* zblue_le_ext_find_adv(uint8_t adv_id)
{
    size_t index;

    for (index = 0; index < ARRAY_SIZE(g_adv_sets); index++) {
        if (!g_adv_sets[index]) {
            continue;
        }

        if (g_adv_sets[index]->adv_id == adv_id) {
            return g_adv_sets[index];
        }
    }

    return NULL;
}

static sal_adapter_req_t* sal_adapter_req(bt_controller_id_t id, uint8_t adv_id, sal_func_t func)
{
    sal_adapter_req_t* req = calloc(sizeof(sal_adapter_req_t), 1);

    if (req) {
        req->id = id;
        req->adv_id = adv_id;
        req->func = func;
    }

    return req;
}

static void sal_invoke_async(service_work_t* work, void* userdata)
{
    sal_adapter_req_t* req = userdata;

    SAL_ASSERT(req);
    req->func(req);
    free(userdata);
}

static bt_status_t sal_send_req(sal_adapter_req_t* req)
{
    if (!req) {
        BT_LOGE("%s, req null", __func__);
        return BT_STATUS_PARM_INVALID;
    }

    if (!service_loop_work((void*)req, sal_invoke_async, NULL)) {
        BT_LOGE("%s, service_loop_work failed", __func__);
        free(req);
        return BT_STATUS_FAIL;
    }

    return BT_STATUS_SUCCESS;
}

static void STACK_CALL(start_adv)(void* args)
{
    sal_adapter_req_t* req = args;
    struct bt_le_ext_adv* adv;
    int ret;
    struct bt_data ad[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
    struct bt_data sd[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
    size_t ad_size = 0;
    size_t sd_size = 0;
    bool ext_supported = bt_le_ext_adv_is_supported();

    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: execute id=%u\n", req->adv_id);
    syslog(LOG_INFO,
        "ov_ble_adv_heap_diag: worker req=%p adv=%p adv_len=%zu scan=%p scan_len=%zu\n",
        req, req->adpt.start_adv.adv_data,
        (size_t)req->adpt.start_adv.adv_len,
        req->adpt.start_adv.scan_rsp_data,
        (size_t)req->adpt.start_adv.scan_rsp_len);

    ret = parse_bt_adv_data(req->adpt.start_adv.adv_data, req->adpt.start_adv.adv_len,
        ad, ARRAY_SIZE(ad), &ad_size);
    if (ret) {
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_adv status=%d\n", ret);
        BT_LOGE("%s, parse adv_data fail, err:%d", __func__, ret);
        goto done;
    }

    ret = parse_bt_adv_data(req->adpt.start_adv.scan_rsp_data, req->adpt.start_adv.scan_rsp_len,
        sd, ARRAY_SIZE(sd), &sd_size);
    if (ret) {
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=parse_scan_rsp status=%d\n", ret);
        BT_LOGE("%s, parse scan_rsp_data fail, ret:%d", __func__, ret);
        goto done;
    }

    if (ext_supported) {
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue create begin id=%u\n", req->adv_id);
        ret = zblue_le_ext_create(&req->adpt.start_adv.param, &adv, req->adv_id);
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue create returned status=%d\n", ret);
        if (ret) {
            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=create status=%d\n", ret);
            BT_LOGE("%s, zblue le ext adv create fail, err:%d", __func__, ret);
            ret = BT_STATUS_FAIL;
            goto done;
        }
        syslog(LOG_INFO,
            "ov_ble_adv_heap_diag: after-create req=%p adv=%p adv_len=%zu scan=%p scan_len=%zu\n",
            req, req->adpt.start_adv.adv_data,
            (size_t)req->adpt.start_adv.adv_len,
            req->adpt.start_adv.scan_rsp_data,
            (size_t)req->adpt.start_adv.scan_rsp_len);

        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue set_data begin id=%u\n", req->adv_id);
        ret = bt_le_ext_adv_set_data(adv, ad_size > 0 ? ad : NULL, ad_size,
            sd_size > 0 ? sd : NULL, sd_size);
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue set_data returned status=%d\n", ret);
        if (ret) {
            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=set_data status=%d\n", ret);
            BT_LOGE("%s, le ext adv set fail, err:%d", __func__, ret);
            ret = BT_STATUS_FAIL;
            goto done;
        }
        syslog(LOG_INFO,
            "ov_ble_adv_heap_diag: after-set-data req=%p adv=%p adv_len=%zu scan=%p scan_len=%zu\n",
            req, req->adpt.start_adv.adv_data,
            (size_t)req->adpt.start_adv.adv_len,
            req->adpt.start_adv.scan_rsp_data,
            (size_t)req->adpt.start_adv.scan_rsp_len);

        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue enable begin id=%u\n", req->adv_id);
        ret = bt_le_ext_adv_start(adv, &req->adpt.start_adv.ext_param);
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: zblue enable returned status=%d\n", ret);
        if (ret) {
            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=enable status=%d\n", ret);
            BT_LOGE("%s, le ext adv start fail, err:%d", __func__, ret);
            ret = BT_STATUS_FAIL;
            goto done;
        }
        syslog(LOG_INFO,
            "ov_ble_adv_heap_diag: after-enable req=%p adv=%p adv_len=%zu scan=%p scan_len=%zu\n",
            req, req->adpt.start_adv.adv_data,
            (size_t)req->adpt.start_adv.adv_len,
            req->adpt.start_adv.scan_rsp_data,
            (size_t)req->adpt.start_adv.scan_rsp_len);
    } else {
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: legacy start begin id=%u\n", req->adv_id);
        ret = bt_le_adv_start(&req->adpt.start_adv.param, ad_size > 0 ? ad : NULL, ad_size,
            sd_size > 0 ? sd : NULL, sd_size);
        syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: legacy start returned status=%d\n", ret);
        if (ret) {
            syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: fail stage=legacy_start status=%d\n", ret);
            BT_LOGE("%s, legacy adv start fail, err:%d", __func__, ret);
            ret = BT_STATUS_FAIL;
            goto done;
        }
    }

    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: state callback begin id=%u\n", req->adv_id);
    syslog(LOG_INFO,
        "ov_ble_adv_heap_diag: before-callback req=%p adv=%p adv_len=%zu scan=%p scan_len=%zu\n",
        req, req->adpt.start_adv.adv_data,
        (size_t)req->adpt.start_adv.adv_len,
        req->adpt.start_adv.scan_rsp_data,
        (size_t)req->adpt.start_adv.scan_rsp_len);
    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STARTED);
    syslog(LOG_INFO, "ov_ble_adv_diag: sal adv: state callback returned id=%u\n", req->adv_id);
    ret = BT_STATUS_SUCCESS;

done:
    syslog(LOG_INFO,
        "ov_ble_adv_heap_diag: pre-free req=%p adv=%p adv_len=%zu scan=%p scan_len=%zu\n",
        req, req->adpt.start_adv.adv_data,
        (size_t)req->adpt.start_adv.adv_len,
        req->adpt.start_adv.scan_rsp_data,
        (size_t)req->adpt.start_adv.scan_rsp_len);

