    38	    uint16_t scan_rsp_len;
    39	    ble_adv_params_t params;
    40	} advertising_info_t;
    41	
    42	typedef struct advertiser {
    43	    struct list_node adver_node;
    44	    void* remote;
    45	    uint8_t adv_id;
    46	    advertiser_callback_t callbacks;
    47	    service_timer_t* adv_start;
    48	} advertiser_t;
    49	
    50	typedef struct {
    51	    bool started;
    52	    index_allocator_t* adv_allocator;
    53	    struct list_node advertiser_list;
    54	} adv_manager_t;
    55	
    56	typedef struct {
    57	    advertiser_t* adver;
    58	    uint8_t adv_id;
    59	    advertising_info_t* adv_info;
    60	    uint8_t state;
    61	} adv_event_t;
    62	
    63	static adv_manager_t adv_manager;
    64	
    65	static void* get_adver(advertiser_t* adver)
    66	{
    67	    return adver->remote ? adver->remote : adver;
    68	}
    69	
    70	static void advertiser_info_free(advertising_info_t* adv_info)
    71	{
    72	    if (adv_info) {
    73	        if (adv_info->adv_data)
    74	            free(adv_info->adv_data);
    75	        if (adv_info->scan_rsp_data)
    76	            free(adv_info->scan_rsp_data);
    77	        free(adv_info);
    78	    }
    79	}
    80	
    81	static advertising_info_t* advertiser_info_copy(ble_adv_params_t* params,
    82	    uint8_t* adv_data,
    83	    uint16_t adv_len,
    84	    uint8_t* scan_rsp_data,
    85	    uint16_t scan_rsp_len)
    86	{
    87	    advertising_info_t* adv_info = calloc(1, sizeof(advertising_info_t));
    88	    if (!adv_info)
    89	        goto fail;
    90	
    91	    if (adv_len && adv_data) {
    92	        adv_info->adv_data = malloc(adv_len);
    93	        if (!adv_info->adv_data)
    94	            goto fail;
    95	        memcpy(adv_info->adv_data, adv_data, adv_len);
    96	        adv_info->adv_len = adv_len;
    97	    }
    98	
    99	    if (scan_rsp_len && scan_rsp_data) {
   100	        adv_info->scan_rsp_data = malloc(scan_rsp_len);
   101	        if (!adv_info->scan_rsp_data)
   102	            goto fail;
   103	        memcpy(adv_info->scan_rsp_data, scan_rsp_data, scan_rsp_len);
   104	        adv_info->scan_rsp_len = scan_rsp_len;
   105	    }
   106	    memcpy(&adv_info->params, params, sizeof(ble_adv_params_t));
   107	
   108	    return adv_info;
   109	fail:
   110	    advertiser_info_free(adv_info);
   111	    return NULL;
   112	}
   113	
   114	static advertiser_t* alloc_new_advertiser(void* remote, const advertiser_callback_t* cbs)
   115	{
   116	    advertiser_t* adver = malloc(sizeof(advertiser_t));
   117	    if (!adver)
   118	        return NULL;
   119	
   120	    adver->remote = remote;
   121	    adver->adv_id = 0;
   122	    adver->adv_start = NULL;
   123	    memcpy(&adver->callbacks, cbs, sizeof(advertiser_callback_t));
   124	
   125	    return adver;
   126	}
   127	
   128	static void destroy_advertiser(advertiser_t* adver)
   129	{
   130	    if (adver->adv_id)
   131	        index_free(adv_manager.adv_allocator, adver->adv_id - 1);
   132	    free(adver);
   133	}
   134	
   135	static void delete_advertiser(advertiser_t* adver)
   136	{
   137	    service_loop_cancel_timer(adver->adv_start);
   138	    adver->adv_start = NULL;
   139	    list_delete(&adver->adver_node);
   140	}
   141	
   142	static bool is_advertiser_exist(advertiser_t* adver)
   143	{
   144	    struct list_node* node;
   145	
   146	    list_for_every(&adv_manager.advertiser_list, node)
   147	    {
   148	        if ((advertiser_t*)node == adver)
   149	            return true;
   150	    }
   151	
   152	    return false;
   153	}
   154	
   155	static advertiser_t* get_advertiser_if_exist(uint8_t adv_id)
   156	{
   157	    struct list_node* node;
   158	
   159	    list_for_every(&adv_manager.advertiser_list, node)
   160	    {
   161	        advertiser_t* adver = (advertiser_t*)node;
   162	        if (adver->adv_id == adv_id)
   163	            return adver;
   164	    }
   165	
   166	    return NULL;
   167	}
   168	
   169	static void start_advertising_timeout(service_timer_t* timer, void* userdata)
   170	{
   171	    advertiser_t* adver = (advertiser_t*)userdata;
   172	
   173	    if (!is_advertiser_exist(adver)) {
   174	        BT_LOGE("%s, timer expeared, adver not found", __func__);
   175	        return;
   176	    }
   177	
   178	    delete_advertiser(adver);
   179	    adver->callbacks.on_advertising_start(get_adver(adver), 0, BT_ADV_STATUS_START_TIMEOUT);
   180	    destroy_advertiser(adver);
   181	}
   182	
   183	static void advertiser_start_event(void* data)
   184	{
   185	    assert(data);
   186	    adv_event_t* start = (adv_event_t*)data;
   187	    advertiser_t* adver = start->adver;
   188	    advertising_info_t* adv_info = start->adv_info;
   189	    int adv_id;
   190	
   191	    free(start);
   192	    if (!adv_manager.started)
   193	        return;
   194	
   195	    adv_id = index_alloc(adv_manager.adv_allocator);
   196	    if (adv_id < 0) {
   197	        adver->callbacks.on_advertising_start(get_adver(adver), 0, BT_ADV_STATUS_START_NOMEM);
   198	        goto fail;
   199	    }
   200	
   201	    adver->adv_id = adv_id + 1;
   202	    if (bt_sal_le_start_adv(0, adver->adv_id, &adv_info->params, adv_info->adv_data,
   203	            adv_info->adv_len, adv_info->scan_rsp_data,
   204	            adv_info->scan_rsp_len)
   205	        != BT_STATUS_SUCCESS) {
   206	        adver->callbacks.on_advertising_start(get_adver(adver), 0, BT_ADV_STATUS_STACK_ERR);
   207	        goto fail;
   208	    }
   209	
   210	    list_add_tail(&adv_manager.advertiser_list, &adver->adver_node);
   211	    advertiser_info_free(adv_info);
   212	    adver->adv_start = service_loop_timer_no_repeating(1000, start_advertising_timeout, adver);
   213	
   214	    return;
   215	fail:
   216	    destroy_advertiser(adver);
   217	    advertiser_info_free(adv_info);
   218	}
   219	
   220	static void advertiser_stop_event(void* data)
   221	{
   222	    assert(data);
   223	    adv_event_t* stop = (adv_event_t*)data;
   224	    advertiser_t* adver = stop->adver;
   225	    uint8_t adv_id = stop->adv_id;
   226	
   227	    free(stop);
   228	    if (!adv_manager.started)
   229	        return;
   230	
   231	    if (adver) {
   232	        if (!is_advertiser_exist(adver)) {
   233	            BT_LOGD("%s, advertiser: %p not exist", __func__, adver);
   234	            return;
   235	        }
   236	    } else {
   237	        adver = get_advertiser_if_exist(adv_id);
   238	        if (!adver) {
   239	            BT_LOGD("%s, adver_id: %d not exist", __func__, adv_id);
   240	            return;
   241	        }
   242	    }
   243	
   244	    bt_sal_le_stop_adv(0, adver->adv_id);
   245	}
   246	
   247	static void advertiser_notify_state(void* data)
   248	{
   249	    adv_event_t* advstate = (adv_event_t*)data;
   250	    advertiser_t* adver;
   251	
   252	    if (!adv_manager.started) {
   253	        goto exit;
   254	    }
   255	
   256	    adver = get_advertiser_if_exist(advstate->adv_id);
   257	    if (!adver) {
   258	        goto exit;
   259	    }
   260	
   261	    if (advstate->state == LE_ADVERTISING_STARTED) {
   262	        service_loop_cancel_timer(adver->adv_start);
   263	        adver->adv_start = NULL;
   264	        adver->callbacks.on_advertising_start(get_adver(adver), advstate->adv_id, BT_ADV_STATUS_SUCCESS);
