   297	void advertising_on_state_changed(uint8_t adv_id, uint8_t state)
   298	{
   299	    adv_event_t* advstate = malloc(sizeof(adv_event_t));
   300	
   301	    if (!advstate) {
   302	        BT_LOGE("adv_id: %d state malloc failed", adv_id);
   303	        return;
   304	    }
   305	
   306	    advstate->adv_id = adv_id;
   307	    advstate->state = state;
   308	    do_in_service_loop(advertiser_notify_state, advstate);
   309	}
