   340	void stop_advertising(bt_advertiser_t* adver)
   341	{
   342	    if (!adapter_is_le_enabled())
   343	        return;
   344	
   345	    adv_event_t* stop = malloc(sizeof(adv_event_t));
   346	    if (!stop)
   347	        return;
   348	
   349	    stop->adver = (advertiser_t*)adver;
   350	    do_in_service_loop(advertiser_stop_event, stop);
   351	}
