   488	static void deferred_timeout(service_timer_t* timer, void* data)
   489	{
   490	    service_loop_t* loop = (service_loop_t*)data;
   491	
   492	    uv_mutex_lock(&loop->msg_lock);
   493	    list_merge(&loop->msg_queue, &loop->deferred_queue);
   494	    uv_mutex_unlock(&loop->msg_lock);
