  1851		if (IS_ENABLED(CONFIG_BT_PERIPHERAL) &&
  1852		    atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
  1853			err = le_adv_start_add_conn(adv, &conn);
