  1855				return err;
  1856			}
  1857		}
  1858	
  1859		atomic_set_bit_to(adv->flags, BT_ADV_LIMITED, param &&
  1860				  (param->timeout > 0 || param->num_events > 0));
  1861	
  1862		if (atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
  1863			if (IS_ENABLED(CONFIG_BT_PRIVACY) &&
  1864			    !atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
  1865				bt_id_set_adv_private_addr(adv);
  1866			}
