  1932	int bt_le_ext_adv_set_data(struct bt_le_ext_adv *adv,
  1933				   const struct bt_data *ad, size_t ad_len,
  1934				   const struct bt_data *sd, size_t sd_len)
  1935	{
  1936		bool ext_adv, scannable;
  1937		uint8_t dev_id = adv->hdev->dev_id;
  1938		int err;
  1939	
  1940		if (dev_id < ARRAY_SIZE(legacy_adv_pending) &&
  1941		    legacy_adv_pending[dev_id].adv == adv) {
  1942			struct bt_le_adv_param *param =
  1943				&legacy_adv_pending[dev_id].param;
  1944	
  1945			legacy_adv_pending[dev_id].adv = NULL;
  1946			if (legacy_adv_data_fits(adv->hdev, param,
  1947						 ad, ad_len, sd, sd_len)) {
  1948				adv->options = param->options |
  1949					       ZBLUE_ADV_OPT_INTERNAL_LEGACY_HCI;
  1950				syslog(LOG_INFO,
  1951				       "ov_ble_adv_diag: zblue adv: selected legacy hci\n");
  1952				err = bt_le_adv_start_legacy(adv, param,
  1953							     ad, ad_len, sd, sd_len);
  1954				if (!err) {
  1955					/* The bt_le_ext_adv_* facade is one-shot on connect. */
  1956					atomic_clear_bit(adv->flags, BT_ADV_PERSIST);
  1957				}
  1958	
  1959				return err;
  1960			}
  1961	
  1962			syslog(LOG_INFO,
  1963			       "ov_ble_adv_diag: zblue adv: selected extended hci\n");
  1964			err = le_ext_adv_param_set(adv, param, false);
  1965			if (err) {
  1966				return err;
  1967			}
  1968		}
  1969	
  1970		ext_adv = atomic_test_bit(adv->flags, BT_ADV_EXT_ADV);
  1971		scannable = atomic_test_bit(adv->flags, BT_ADV_SCANNABLE);
  1972	
  1973		if (ext_adv) {
  1974			if ((scannable && ad_len) ||
  1975			    (!scannable && sd_len)) {
  1976				return -ENOTSUP;
  1977			}
  1978		}
