   606	static int hci_set_ad(struct bt_dev *hdev, uint16_t hci_op, const struct bt_ad *ad, size_t ad_len)
   607	{
   608		struct bt_hci_cp_le_set_adv_data *set_data;
   609		struct net_buf *buf;
   610		int err;
   611	
   612		buf = bt_hci_cmd_create(hci_op, sizeof(*set_data));
   613		if (!buf) {
   614			return -ENOBUFS;
   615		}
   616	
   617		set_data = net_buf_add(buf, sizeof(*set_data));
   618		(void)memset(set_data, 0, sizeof(*set_data));
   619	
   620		err = set_data_add_complete(set_data->data, BT_GAP_ADV_MAX_ADV_DATA_LEN,
   621					    ad, ad_len, &set_data->len);
   622		if (err) {
   623			net_buf_unref(buf);
