   630	static int hci_set_adv_ext_complete(struct bt_le_ext_adv *adv, uint16_t hci_op,
   631					    size_t total_data_len, const struct bt_ad *ad, size_t ad_len)
   632	{
   633		struct bt_hci_cp_le_set_ext_adv_data *set_data;
   634		struct net_buf *buf;
   635		size_t cmd_size;
   636		int err;
   637	
   638		/* Provide the opportunity to truncate the complete name */
   639		if (!atomic_test_bit(adv->flags, BT_ADV_EXT_ADV) &&
