   641			total_data_len = BT_GAP_ADV_MAX_ADV_DATA_LEN;
   642		}
   643	
   644		cmd_size = sizeof(*set_data) + total_data_len;
   645	
   646		buf = bt_hci_cmd_create(hci_op, cmd_size);
   647		if (!buf) {
   648			return -ENOBUFS;
   649		}
   650	
   651		set_data = net_buf_add(buf, cmd_size);
   652		(void)memset(set_data, 0, cmd_size);
   653	
   654		err = set_data_add_complete(set_data->data, total_data_len,
   655					    ad, ad_len, &set_data->len);
   656		if (err) {
   657			net_buf_unref(buf);
   658			return err;
   659		}
   660	
   661		set_data->handle = adv->handle;
   662		set_data->op = BT_HCI_LE_EXT_ADV_OP_COMPLETE_DATA;
   663		set_data->frag_pref = BT_HCI_LE_EXT_ADV_FRAG_DISABLED;
   664	
