   668	static int hci_set_adv_ext_fragmented(struct bt_le_ext_adv *adv, uint16_t hci_op,
   669					      const struct bt_ad *ad, size_t ad_len)
   670	{
   671		int err;
   672		struct ad_stream stream;
   673		bool is_first_iteration = true;
   674	
   675		err = ad_stream_new(&stream, ad, ad_len);
   676		if (err) {
   677			return err;
   678		}
   679	
   680		while (!ad_stream_is_empty(&stream)) {
   681			struct bt_hci_cp_le_set_ext_adv_data *set_data;
   682			struct net_buf *buf;
   683			const size_t data_len = MIN(BT_HCI_LE_EXT_ADV_FRAG_MAX_LEN, stream.remaining_size);
   684			const size_t cmd_size = sizeof(*set_data) + data_len;
   685	
   686			buf = bt_hci_cmd_create(hci_op, cmd_size);
   687			if (!buf) {
   688				return -ENOBUFS;
   689			}
   690	
   691			set_data = net_buf_add(buf, cmd_size);
   692	
   693			set_data->handle = adv->handle;
   694			set_data->frag_pref = BT_HCI_LE_EXT_ADV_FRAG_ENABLED;
   695			set_data->len = ad_stream_read(&stream, set_data->data, data_len);
   696	
   697			if (is_first_iteration && ad_stream_is_empty(&stream)) {
   698				set_data->op = BT_HCI_LE_EXT_ADV_OP_COMPLETE_DATA;
   699			} else if (is_first_iteration) {
   700				set_data->op = BT_HCI_LE_EXT_ADV_OP_FIRST_FRAG;
   701			} else if (ad_stream_is_empty(&stream)) {
   702				set_data->op = BT_HCI_LE_EXT_ADV_OP_LAST_FRAG;
   703			} else {
   704				set_data->op = BT_HCI_LE_EXT_ADV_OP_INTERM_FRAG;
   705			}
   706	
   707			err = bt_hci_cmd_send_sync(adv->hdev, hci_op, buf, NULL);
   708			if (err) {
   709				return err;
   710			}
   711	
   712			is_first_iteration = false;
   713		}
   714	
   715		return 0;
   716	}
