   630	static int hci_set_adv_ext_complete(struct bt_le_ext_adv *adv, uint16_t hci_op,
   631					    size_t total_data_len, const struct bt_ad *ad, size_t ad_len)
   632	{
   633		struct bt_hci_cp_le_set_ext_adv_data *set_data;
   634		struct net_buf *buf;
   635		size_t cmd_size;
   636		int err;
   637	
   638		/* Provide the opportunity to truncate the complete name */
   639		if (!atomic_test_bit(adv->flags, BT_ADV_EXT_ADV) &&
   640		    total_data_len > BT_GAP_ADV_MAX_ADV_DATA_LEN) {
   641			total_data_len = BT_GAP_ADV_MAX_ADV_DATA_LEN;
   642		}
   643	
   644		cmd_size = sizeof(*set_data) + total_data_len;
   645	
   646		buf = bt_hci_cmd_create(hci_op, cmd_size);
   647		if (!buf) {
   648			return -ENOBUFS;
   649		}
   650	
   651		set_data = net_buf_add(buf, cmd_size);
   652		(void)memset(set_data, 0, cmd_size);
   653	
   654		err = set_data_add_complete(set_data->data, total_data_len,
   655					    ad, ad_len, &set_data->len);
   656		if (err) {
   657			net_buf_unref(buf);
   658			return err;
   659		}
   660	
   661		set_data->handle = adv->handle;
   662		set_data->op = BT_HCI_LE_EXT_ADV_OP_COMPLETE_DATA;
   663		set_data->frag_pref = BT_HCI_LE_EXT_ADV_FRAG_DISABLED;
   664	
   665		return bt_hci_cmd_send_sync(adv->hdev, hci_op, buf, NULL);
   666	}
