   718	static int hci_set_ad_ext(struct bt_le_ext_adv *adv, uint16_t hci_op,
   719				  const struct bt_ad *ad, size_t ad_len)
   720	{
   721		size_t total_len_bytes = 0;
   722	
   723		for (size_t i = 0; i < ad_len; i++) {
   724			for (size_t j = 0; j < ad[i].len; j++) {
   725				total_len_bytes += ad[i].data[j].data_len + 2;
   726			}
   727		}
   728	
   729		if ((total_len_bytes > BT_HCI_LE_EXT_ADV_FRAG_MAX_LEN) &&
   730		    atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
   731			/* It is not allowed to set advertising data in multiple
   732			 * operations while the advertiser is running.
   733			 */
   734			return -EAGAIN;
   735		}
   736	
   737		if (total_len_bytes > adv->hdev->le.max_adv_data_len) {
   738			LOG_WRN("adv or scan rsp data too large (%zu > max %u)", total_len_bytes,
   739				adv->hdev->le.max_adv_data_len);
   740			return -EDOM;
   741		}
   742	
   743		if (total_len_bytes <= BT_HCI_LE_EXT_ADV_FRAG_MAX_LEN) {
   744			/* If possible, set all data at once.
   745			 * This allows us to update advertising data while advertising.
   746			 */
   747			return hci_set_adv_ext_complete(adv, hci_op, total_len_bytes, ad, ad_len);
   748		} else {
   749			return hci_set_adv_ext_fragmented(adv, hci_op, ad, ad_len);
   750		}
   751	
   752		return 0;
   753	}
