   567	static int set_data_add_complete(uint8_t *set_data, uint8_t set_data_len_max,
   568				const struct bt_ad *ad, size_t ad_len, uint8_t *data_len)
   569	{
   570		uint8_t set_data_len = 0;
   571	
   572		for (size_t i = 0; i < ad_len; i++) {
   573			const struct bt_data *data = ad[i].data;
   574	
   575			for (size_t j = 0; j < ad[i].len; j++) {
   576				size_t len = data[j].data_len;
   577				uint8_t type = data[j].type;
   578	
   579				/* Check if ad fit in the remaining buffer */
   580				if ((set_data_len + len + 2) > set_data_len_max) {
   581					ssize_t shortened_len = set_data_len_max -
   582								(set_data_len + 2);
   583	
   584					if (!(type == BT_DATA_NAME_COMPLETE &&
   585					      shortened_len > 0)) {
   586						LOG_ERR("Too big advertising data");
   587						return -EINVAL;
   588					}
   589	
   590					type = BT_DATA_NAME_SHORTENED;
   591					len = shortened_len;
   592				}
   593	
   594				set_data[set_data_len++] = len + 1;
   595				set_data[set_data_len++] = type;
   596	
   597				memcpy(&set_data[set_data_len], data[j].data, len);
   598				set_data_len += len;
   599			}
   600		}
   601	
   602		*data_len = set_data_len;
   603		return 0;
   604	}
