   399	static void sal_invoke_async(service_work_t* work, void* userdata)
   400	{
   401	    sal_adapter_req_t* req = userdata;
   402	
   403	    SAL_ASSERT(req);
   404	    req->func(req);
   405	    free(userdata);
   406	}
   407	
   408	static bt_status_t sal_send_req(sal_adapter_req_t* req)
   409	{
   410	    if (!req) {
   411	        BT_LOGE("%s, req null", __func__);
   412	        return BT_STATUS_PARM_INVALID;
   413	    }
   414	
   415	    if (!service_loop_work((void*)req, sal_invoke_async, NULL)) {
   416	        BT_LOGE("%s, service_loop_work failed", __func__);
   417	        free(req);
   418	        return BT_STATUS_FAIL;
   419	    }
   420	
   421	    return BT_STATUS_SUCCESS;
   422	}
