+#define ZBLUE_ADV_OPT_INTERNAL_LEGACY_HCI BIT(31)
+
+struct legacy_adv_pending {
+	struct bt_le_ext_adv *adv;
+	struct bt_le_adv_param param;
+};
+
+static struct legacy_adv_pending legacy_adv_pending[CONFIG_BT_NUM_CTLRS];
+
+static bool ov_ble_adv_diag_param(const struct bt_le_adv_param *param)
+{
+	return !(param->options & BT_LE_ADV_OPT_EXT_ADV) &&
+	       (param->options & _BT_LE_ADV_OPT_CONNECTABLE) &&
+	       (param->options & BT_LE_ADV_OPT_SCANNABLE);
+}
+
+static bool ov_ble_adv_diag_set(const struct bt_le_ext_adv *adv)
+{
+	return !atomic_test_bit(adv->flags, BT_ADV_EXT_ADV) &&
+	       atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE) &&
+	       atomic_test_bit(adv->flags, BT_ADV_SCANNABLE);
+}
+
+struct ov_ble_adv_buf_snapshot {
+	void *buf;
+	void *data;
+	void *cp;
+	void *storage_begin;
+	void *storage_end;
+	unsigned int buf_len;
+	unsigned int tailroom;
+};
+
+static bool ov_ble_adv_buf_diag_opcode(uint16_t opcode)
+{
+	return opcode == BT_HCI_OP_LE_SET_EXT_ADV_PARAM ||
+	       opcode == BT_HCI_OP_LE_SET_EXT_ADV_DATA ||
+	       opcode == BT_HCI_OP_LE_SET_EXT_SCAN_RSP_DATA;
+}
+
+static struct ov_ble_adv_buf_snapshot ov_ble_adv_buf_snapshot(struct net_buf *buf,
+							       void *cp)
+{
+	size_t headroom = net_buf_headroom(buf);
+	size_t tailroom = net_buf_tailroom(buf);
+	struct ov_ble_adv_buf_snapshot snapshot = {
+		.buf = buf,
+		.data = buf->data,
+		.cp = cp,
+		.storage_begin = buf->data - headroom,
+		.storage_end = buf->data + buf->len + tailroom,
+		.buf_len = buf->len,
+		.tailroom = tailroom,
+	};
+
+	return snapshot;
+}
+
+static void ov_ble_adv_buf_diag(uint16_t opcode, const char *phase,
+				const struct ov_ble_adv_buf_snapshot *snapshot)
+{
+	syslog(LOG_INFO,
+	       "ov_ble_adv_buf_diag: opcode=0x%04x phase=%s buf=%p data=%p cp=%p storage_begin=%p storage_end=%p buf_len=%u tailroom=%u\n",
+	       opcode, phase, snapshot->buf, snapshot->data, snapshot->cp,
+	       snapshot->storage_begin, snapshot->storage_end,
+	       snapshot->buf_len, snapshot->tailroom);
+}
+
+bool bt_le_adv_uses_legacy_hci(const struct bt_le_ext_adv *adv)
+{
+	return adv && (adv->options & ZBLUE_ADV_OPT_INTERNAL_LEGACY_HCI);
+}
+
+void bt_le_adv_legacy_connected(struct bt_le_ext_adv *adv,
+				struct bt_conn *conn)
+{
+#if defined(CONFIG_BT_EXT_ADV)
+	if (adv && adv->cb && adv->cb->connected) {
+		struct bt_le_ext_adv_connected_info info = {
+			.conn = conn,
+		};
+
+		adv->cb->connected(adv, &info);
+	}
+#else
+	ARG_UNUSED(adv);
+	ARG_UNUSED(conn);
+#endif
+}
