 675	static int hci_set_adv_ext_complete(struct bt_le_ext_adv *adv, uint16_t hci_op,
 676					    size_t total_data_len, const struct bt_ad *ad, size_t ad_len)
 677	{
 678		struct bt_hci_cp_le_set_ext_adv_data *set_data;
 679		struct ov_ble_adv_buf_snapshot snapshot;
 680		struct net_buf *buf;
 681		size_t cmd_size;
 682		bool diag;
 683		int err;
 684	
 685		/* Provide the opportunity to truncate the complete name */
 686		if (!atomic_test_bit(adv->flags, BT_ADV_EXT_ADV) &&
 687		    total_data_len > BT_GAP_ADV_MAX_ADV_DATA_LEN) {
 688			total_data_len = BT_GAP_ADV_MAX_ADV_DATA_LEN;
 689		}
 690	
 691		cmd_size = sizeof(*set_data) + total_data_len;
 692	
 693		buf = bt_hci_cmd_create(hci_op, cmd_size);
 694		if (!buf) {
 695			return -ENOBUFS;
 696		}
 697		diag = ov_ble_adv_buf_diag_opcode(hci_op);
 698		if (diag) {
 699			snapshot = ov_ble_adv_buf_snapshot(buf, NULL);
 700			ov_ble_adv_buf_diag(hci_op, "create", &snapshot);
 701		}
 702	
 703		set_data = net_buf_add(buf, cmd_size);
 704		if (diag) {
 705			snapshot = ov_ble_adv_buf_snapshot(buf, set_data);
 706			ov_ble_adv_buf_diag(hci_op, "add", &snapshot);
 707		}
 708		(void)memset(set_data, 0, cmd_size);
 709	
 710		err = set_data_add_complete(set_data->data, total_data_len,
 711					    ad, ad_len, &set_data->len);
 712		if (err) {
 713			net_buf_unref(buf);
 714			return err;
 715		}
 716	
 717		set_data->handle = adv->handle;
 718		set_data->op = BT_HCI_LE_EXT_ADV_OP_COMPLETE_DATA;
 719		set_data->frag_pref = BT_HCI_LE_EXT_ADV_FRAG_DISABLED;
 720	
 721		if (diag) {
 722			snapshot = ov_ble_adv_buf_snapshot(buf, set_data);
 723			ov_ble_adv_buf_diag(hci_op, "built", &snapshot);
 724		}
 725		err = bt_hci_cmd_send_sync(adv->hdev, hci_op, buf, NULL);
 726		if (diag) {
 727			ov_ble_adv_buf_diag(hci_op, "send-return", &snapshot);
 728		}
 729	
 730		return err;
 731	}
