  62	static bool ov_ble_adv_buf_diag_opcode(uint16_t opcode)
  63	{
  64		return opcode == BT_HCI_OP_LE_SET_EXT_ADV_PARAM ||
  65		       opcode == BT_HCI_OP_LE_SET_EXT_ADV_DATA ||
  66		       opcode == BT_HCI_OP_LE_SET_EXT_SCAN_RSP_DATA;
