  68	
  69	static struct ov_ble_adv_buf_snapshot ov_ble_adv_buf_snapshot(struct net_buf *buf,
  70								       void *cp)
  71	{
  72		size_t headroom = net_buf_headroom(buf);
  73		size_t tailroom = net_buf_tailroom(buf);
  74		struct ov_ble_adv_buf_snapshot snapshot = {
  75			.buf = buf,
  76			.data = buf->data,
  77			.cp = cp,
  78			.storage_begin = buf->data - headroom,
  79			.storage_end = buf->data + buf->len + tailroom,
  80			.buf_len = buf->len,
  81			.tailroom = tailroom,
  82		};
  83	
  84		return snapshot;
  85	}
