562	    }
563	
564	  if (priv->drop_rx_until_tx)
565	    {
632	static int sf32lb52_bt_send(struct bt_driver_s *drv,
633	                            enum bt_buf_type_e type,
634	                            void *data, size_t len)
635	{
636	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
637	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
638	  uint16_t opcode;
639	  int ret;
640	
641	  switch (type)
642	    {
643	      case BT_CMD:
644	        *hdr = H4_CMD;
645	        break;
646	      case BT_ACL_OUT:
647	        *hdr = H4_ACL;
648	        break;
649	      case BT_ISO_OUT:
650	        *hdr = H4_ISO;
651	        break;
652	      default:
653	        return -EINVAL;
654	    }
655	
656	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
657	    {
658	      opcode = sf32lb52_bt_get_le16(data);
659	
660	      if (sf32lb52_bt_is_adv_diag_opcode(opcode) &&
661	          len >= sizeof(struct bt_hci_cmd_hdr_s) + ((uint8_t *)data)[2])
662	        {
663	          syslog(LOG_INFO,
664	                 "ov_ble_adv_diag: h4: command tx opcode=0x%04x\n",
665	                 opcode);
666	        }
667	
668	  #if SF32LB52_BT_TRACE
669	    syslog(LOG_INFO,
670	            "sf32lb52 bth4 hci tx: opcode=0x%04x len=%lu\n",
671	            opcode, (unsigned long)len);
672	    #endif
673	
674	  #if SF32LB52_BT_COMPAT_BR_INIT
675	    if (opcode == BT_HCI_OP_WRITE_LOCAL_NAME)
676	      {
677	        syslog(LOG_INFO,
678	               "sf32lb52 bth4 compat: synth BR init opcode=0x%04x\n",
679	               opcode);
680	        ret = sf32lb52_bt_synth_status_complete(priv, opcode);
681	        return ret < 0 ? ret : len;
682	      }
683	    #endif
684	
685	  #if SF32LB52_BT_EMULATE_HCI
686	    if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
687	    {
688	      return ret < 0 ? ret : len;
689	    }
690	    #endif
691	
692	  ret = sf32lb52_bt_ensure_controller_enabled(opcode);
693	      if (ret < 0)
694	        {
695	          return ret;
696	        }
697	    }
698	  else
699	    {
700	      ret = sf32lb52_bt_ensure_controller_enabled(0);
701	      if (ret < 0)
702	        {
703	          return ret;
704	        }
705	    }
706	
707	  priv->drop_rx_until_tx = false;
708	
709	  if (SF32LB52_BT_TRACE_ACL && type == BT_ACL_OUT)
710	    {
711	      syslog(LOG_INFO,
712	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
713	             (unsigned int)type,
714	             (unsigned long)(len + drv->head_reserve),
715	             hdr[0],
716	             len >= 1 ? hdr[1] : 0,
717	             len >= 2 ? hdr[2] : 0,
718	             len >= 3 ? hdr[3] : 0,
719	             len >= 4 ? hdr[4] : 0);
720	    }
721	
722	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
723	  if (ret < 0)
724	    {
725	      return ret;
726	    }
727	
728	  return len;
729	}
