324	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
325	                                     uint32_t *rd_ptr,
326	                                     uint32_t *wr_ptr)
327	{
328	  uint32_t rd;
329	  uint32_t wr;
330	
331	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
332	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
333	                       sizeof(*tx_ring));
334	
335	  rd = tx_ring->read_idx_mirror;
336	  wr = tx_ring->write_idx_mirror;
