133	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
134	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
135	  long buf_size = rx_ring->buffer_size;
136	
137	  if (!sf32lb52_bt_rx_ring_valid(rx_ring))
138	    {
139	      syslog(LOG_WARNING,
140	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
141	             tag,
142	             buf_size,
143	             (unsigned long)SF32LB52_BT_RING_DATA_SIZE,
144	             (unsigned long)rd_ptr,
145	             (unsigned long)wr_ptr);
