250	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
251	                                    const struct circular_buf *rx_ring,
252	                                    uint32_t rd_ptr,
253	                                    size_t len)
254	{
255	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
256	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
257	  size_t tail;
258	
259	  if (len == 0)
260	    {
261	      return 0;
262	    }
263	
264	  tail = rx_ring->buffer_size - rd_idx;
265	  if (tail >= len)
266	    {
267	      memcpy(dst, &pool[rd_idx], len);
268	      return len;
269	    }
270	
271	  memcpy(dst, &pool[rd_idx], tail);
272	  memcpy(&dst[tail], pool, len - tail);
273	  return len;
274	}
