276	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
277	                                     const uint8_t *src, size_t len)
278	{
279	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
280	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
281	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
282	  size_t space;
283	  size_t tail;
284	
285	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
286	                                     wr_ptr,
287	                                     tx_ring->buffer_size);
288	  if (space == 0)
289	    {
290	      return 0;
291	    }
292	
293	  if (len > space)
294	    {
295	      len = space;
296	    }
297	
298	  tail = tx_ring->buffer_size - wr_idx;
299	  if (tail >= len)
300	    {
301	      memcpy(&pool[wr_idx], src, len);
302	      up_clean_dcache((uintptr_t)&pool[wr_idx],
303	                      (uintptr_t)&pool[wr_idx] + len);
304	    }
305	  else
306	    {
307	      memcpy(&pool[wr_idx], src, tail);
308	      memcpy(pool, &src[tail], len - tail);
309	      up_clean_dcache((uintptr_t)&pool[wr_idx],
310	                      (uintptr_t)&pool[wr_idx] + tail);
311	      up_clean_dcache((uintptr_t)pool,
312	                      (uintptr_t)pool + len - tail);
313	    }
314	
315	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
316	                                                       tx_ring->buffer_size);
317	  up_clean_dcache((uintptr_t)tx_ring,
318	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
319	  __DSB();
320	
321	  return len;
322	}
