338	  if (rd_ptr != NULL)
339	    {
340	      *rd_ptr = rd;
341	    }
342	
343	  if (wr_ptr != NULL)
344	    {
345	      *wr_ptr = wr;
346	    }
347	
348	  return sf32lb52_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
349	}
