117	static bool sf32lb52_bt_rx_ring_valid(struct circular_buf *rx_ring)
118	{
119	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
120	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
121	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
122	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
123	  long buf_size = rx_ring->buffer_size;
124	
125	  return buf_size == (long)SF32LB52_BT_RING_DATA_SIZE &&
126	         rd_idx <= SF32LB52_BT_RING_DATA_SIZE &&
127	         wr_idx <= SF32LB52_BT_RING_DATA_SIZE;
