153	{
154	  struct circular_buf *rx_ring =
155	      (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
156	  int i;
157	
158	  for (i = 0; i < 1000; i++)
159	    {
160	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
161	                           (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
162	                           SF32LB52_BT_RX_BUF_SIZE);
163	
164	      if (sf32lb52_bt_rx_ring_valid(rx_ring))
