332	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
333	                       sizeof(*tx_ring));
334	
335	  rd = tx_ring->read_idx_mirror;
336	  wr = tx_ring->write_idx_mirror;
337	
338	  if (rd_ptr != NULL)
339	    {
340	      *rd_ptr = rd;
341	    }
342	
343	  if (wr_ptr != NULL)
344	    {
345	      *wr_ptr = wr;
346	    }
