562	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
563	{
564	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
565	  irqstate_t flags;
566	  bool queue_work;
567	  bool work_ready;
568	  bool report_exit_window = false;
569	
570	  if (handle != env->ipc_port)
571	    {
572	      return -EINVAL;
573	    }
574	
575	  if (!env->queue_open)
576	    {
577	      struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
578	      #if SF32LB52_BT_TRACE
579	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
580	              (unsigned long)rx_ring->write_idx_mirror,
581	              (unsigned long)rx_ring->read_idx_mirror);
582	      #endif
583	      return OK;
584	    }
585	
586	  flags = enter_critical_section();
587	  env->rx_work_pending = true;
588	  work_ready = work_available(&env->rx_work);
589	  queue_work = !env->rx_worker_running && work_ready;
590	  if (queue_work)
591	    {
592	      env->rx_worker_running = true;
593	      env->rx_exit_window_reported = false;
594	    }
595	  else if (!env->rx_worker_running && !work_ready &&
596	           !env->rx_exit_window_reported)
597	    {
598	      env->rx_exit_window_reported = true;
599	      report_exit_window = true;
600	    }
601	  leave_critical_section(flags);
602	
603	  if (report_exit_window)
604	    {
605	      syslog(LOG_WARNING, "sf32lb52 bt RX worker exit window hit\n");
606	    }
607	
608	#if SF32LB52_BT_TRACE
609	  {
610	    struct circular_buf *rx_ring =
611	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
612	
613	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
614	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
615	                         sizeof(*rx_ring));
616	
617	    syslog(LOG_INFO,
618	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
619	           (unsigned long)size,
620	           (unsigned long)env->rx_read_idx_mirror,
621	           (unsigned long)rx_ring->read_idx_mirror,
622	           (unsigned long)rx_ring->write_idx_mirror);
623	  }
624	#endif
625	
626	  if (queue_work)
627	    {
628	      int ret;
629	
630	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
631	                       env, 0);
632	      if (ret < 0)
633	        {
