   833	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
   834	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
   835	
   836	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   837	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   838	                    sizeof(*rx_ring));
   839	    __DSB();
   840	  }
