   206	static size_t sf32lb52_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
   207	                                        uint32_t buffer_size)
   208	{
   209	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
   210	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
   211	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
   212	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
   213	
   214	  if (rd_idx == wr_idx)
   215	    {
   216	      return rd_mirror == wr_mirror ? 0 : buffer_size;
   217	    }
   218	
   219	  if (wr_idx > rd_idx)
   220	    {
   221	      return wr_idx - rd_idx;
   222	    }
   223	
   224	  return buffer_size - (rd_idx - wr_idx);
   225	}
