   234	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
   235	                                         uint32_t buffer_size)
   236	{
   237	  uint32_t idx = CB_GET_PTR_IDX(ptr);
   238	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
