908	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
909	{
910	  struct circular_buf *tx_ring =
911	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
912	  uint32_t start_time;
913	  uint32_t tick_count;
914	  size_t written;
915	  size_t remaining;
916	  size_t offset;
917	  size_t chunk;
918	  size_t chunks;
919	  uint32_t wr_ptr;
920	  int ret;
921	
922	  if (data == NULL || len == 0)
923	    {
924	      return -EINVAL;
925	    }
926	
927	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
928	      !g_sf32lb52_bt_env.queue_open)
929	    {
930	      return -ENODEV;
931	    }
932	
933	  offset = 0;
934	  remaining = len;
935	  start_time = HAL_GetTick();
936	  tick_count = 0;
937	  chunks = 0;
938	  wr_ptr = 0;
939	
940	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
941	  if (ret < 0)
942	    {
943	      return ret;
944	    }
945	
946	  while (remaining > 0)
947	    {
948	      irqstate_t flags;
949	
950	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
951	
952	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
953	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
954	                           sizeof(*tx_ring));
955	
956	      flags = enter_critical_section();
957	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
958	      leave_critical_section(flags);
959	
960	      if (written == 0)
961	        {
962	          if (HAL_GetTick() != start_time)
963	            {
964	              tick_count++;
965	              start_time = HAL_GetTick();
966	            }
967	
968	          if (tick_count >= 10)
969	            {
970	              syslog(LOG_ERR,
971	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
972	                     (unsigned long)remaining);
973	              return -ETIMEDOUT;
974	            }
975	
976	          continue;
977	        }
978	
979	      offset += written;
980	      remaining -= written;
981	
982	      __DSB();
983	      wr_ptr = tx_ring->write_idx_mirror;
984	      sf32lb52_bt_trigger_tx();
985	      chunks++;
986	    }
987	
988	#if SF32LB52_BT_TRACE
989	  syslog(LOG_INFO,
990	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
991	         len,
992	         (unsigned long)chunks,
993	         (unsigned long)wr_ptr,
994	         data[0]);
