   607	int bt_hci_le_rand_mc(uint8_t dev_id, void *buffer, size_t len)
   608	{
   609		struct bt_hci_rp_le_rand *rp;
   610		struct net_buf *rsp;
   611		size_t count;
   612		int err;
   613		struct bt_dev *hdev;
   614	
   615		hdev = bt_dev_get(dev_id);
   616		if (!hdev) {
   617			return -ENODEV;
   618		}
   619	
   620		/* Check first that HCI_LE_Rand is supported */
   621		if (!BT_CMD_TEST(hdev->supported_commands, 27, 7)) {
   622			return -ENOTSUP;
   623		}
   624	
   625		while (len > 0) {
   626			/* Number of bytes to fill on this iteration */
   627			count = MIN(len, sizeof(rp->rand));
   628			/* Request the next 8 bytes over HCI */
   629			err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_LE_RAND, NULL, &rsp);
   630			if (err) {
   631				return err;
   632			}
   633			/* Copy random data into buffer */
   634			rp = (void *)rsp->data;
   635			memcpy(buffer, rp->rand, count);
   636	
   637			net_buf_unref(rsp);
   638			buffer = (uint8_t *)buffer + count;
   639			len -= count;
   640		}
   641	
   642		return 0;
   643	}
