 517	static void *probe_communication_thread(void *arg)
 518	{
 519	  struct probe_rx_slot_s slot;
 520	  bt_address_t peer_addr;
 521	  uint32_t generation;
 522	  uint32_t active_generation = 0;
 523	  bool connected;
 524	  bool have_slot;
 525	  int wait_status;
 526	
 527	  (void)arg;
 528	
 529	  for (;;)
 530	    {
 531	      do
 532	        {
 533	          wait_status = sem_wait(&g_rx_sem);
 534	        }
 535	      while (wait_status < 0 && errno == EINTR);
 536	
 537	      if (wait_status < 0)
 538	        {
 539	          continue;
 540	        }
 541	
 542	      pthread_mutex_lock(&g_rx_lock);
 543	      have_slot = g_rx_count > 0;
 544	      if (have_slot)
 545	        {
 546	          memcpy(&slot, &g_rx_queue[g_rx_tail], sizeof(slot));
 547	          g_rx_tail = (g_rx_tail + 1) % PROBE_RX_QUEUE_DEPTH;
 548	          g_rx_count--;
 549	        }
 550	      pthread_mutex_unlock(&g_rx_lock);
 551	
 552	      pthread_mutex_lock(&g_state_lock);
 553	      generation = g_connection_generation;
 554	      connected = g_peer_connected;
 555	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
 556	      pthread_mutex_unlock(&g_state_lock);
 557	
 558	      if (generation != active_generation)
 559	        {
 560	          memset(&g_throughput, 0, sizeof(g_throughput));
 561	          active_generation = generation;
 562	        }
 563	
 564	      if (!have_slot)
 565	        {
 566	          continue;
 567	        }
 568	
 569	      if (!connected || slot.connection_generation != generation ||
 570	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
 571	        {
 572	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
 573	          continue;
 574	        }
 575	
 590	    GATT_PERM_WRITE,
 591	    NULL, probe_rx_written, PROBE_RX_HANDLE),
 592	
 593	  GATT_H_CHARACTERISTIC_AUTO_RSP(
 594	    BT_UUID_DECLARE_16(PROBE_TX_UUID),
 595	    GATT_PROP_NOTIFY, 0, NULL, 0, PROBE_TX_HANDLE),
 596	
 597	  GATT_H_CCCD(GATT_PERM_READ | GATT_PERM_WRITE,
 598	              probe_tx_cccd_written, PROBE_TX_CCCD_HANDLE),
 599	};
