 948	      return 1;
 949	    }
 950	
 951	  if (sem_init(&g_rx_sem, 0, 0) < 0)
 952	    {
 953	      printf("openvela_ble_probe: RX semaphore init failed\n");
 954	      return 1;
 955	    }
 956	
 957	  if (init_gatt_service() < 0)
 958	    {
 959	      return 1;
 960	    }
