 966	      printf("openvela_ble_probe: communication thread create failed:%d\n",
 967	             ret);
 968	      return 1;
 969	    }
 970	
 971	  printf("openvela_ble_probe: delaying advertising 100 ms after GATT "
 972	         "table setup\n");
 973	  usleep(100000);
 974	
 975	  if (start_advertising() < 0)
 976	    {
 977	      return 1;
 978	    }
 979	
 980	  for (;;)
 981	    {
 982	      usleep(100000);
 983	
 984	#if BLE_PROBE_ENABLE_AUTO_2M_PHY
 985	      do_phy_read = false;
 986	      do_phy_update = false;
 987	
 988	      pthread_mutex_lock(&g_state_lock);
 989	      generation = g_connection_generation;
 990	      if (g_peer_connected && g_phy_read_pending &&
 991	          !g_phy_read_requested)
 992	        {
 993	          g_phy_read_pending = false;
 994	          g_phy_read_requested = true;
 995	          memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
 996	          do_phy_read = true;
 997	        }
 998	      else if (g_peer_connected && g_phy_update_pending &&
 999	               !g_phy_update_requested)
1000	        {
1001	          g_phy_update_pending = false;
1002	          g_phy_update_requested = true;
1003	          memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
1004	          do_phy_update = true;
1005	        }
1006	      pthread_mutex_unlock(&g_state_lock);
1007	
1008	      if (do_phy_read)
1009	        {
1010	          status = bt_gatts_read_phy(g_service_handle, &peer_addr);
1011	          printf("openvela_ble_probe: PHY read request status=%d\n",
1012	                 status);
1013	
1014	          if (status == BT_STATUS_SUCCESS)
1015	            {
1016	              pthread_mutex_lock(&g_state_lock);
1017	              if (g_peer_connected &&
1018	                  generation == g_connection_generation)
1019	                {
1020	                  g_phy_update_pending = true;
1021	                }
1022	              pthread_mutex_unlock(&g_state_lock);
1023	            }
1024	
1025	          continue;
1026	        }
1027	
1028	      if (do_phy_update)
1029	        {
1030	          status = bt_gatts_update_phy(g_service_handle, &peer_addr,
1031	                                       BT_LE_2M_PHY, BT_LE_2M_PHY);
