 107	static int probe_parse_startup_uptime(int argc, char *argv[],
 108	                                      uint64_t *target_ms)
 109	{
 110	  const char *cursor;
 111	  uint32_t value = 0;
 112	
 113	  if (argc == 1)
 114	    {
 115	      *target_ms = MIN_BLE_STARTUP_UPTIME_MS;
 116	      return 0;
 117	    }
 118	
 119	  if (argc == 2 && argv[1][0] != '\0')
 120	    {
 121	      for (cursor = argv[1]; *cursor != '\0'; cursor++)
 122	        {
 123	          if (*cursor < '0' || *cursor > '9')
 124	            {
 125	              goto invalid;
 450	      probe_print_rx_queue_stats();
 451	      memset(&g_throughput, 0, sizeof(g_throughput));
 452	      return;
 453	    }
 454	  else
 455	    {
 456	      reply = g_error;
 457	      reply_len = sizeof(g_error);
 458	      printf("openvela_ble_probe: RX unknown command\n");
 459	    }
 460	
 461	  status = probe_notify(srv_handle, reply, reply_len);
 462	  printf("openvela_ble_probe: TX notify status=%d\n", status);
 463	}
