 465	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
 466	                                 bt_address_t *addr,
 467	                                 uint16_t attr_handle,
 468	                                 const uint8_t *value,
 469	                                 uint16_t length,
 470	                                 uint16_t offset)
 471	{
 472	  struct probe_rx_slot_s *slot;
 473	  uint32_t generation;
 474	
 475	  (void)srv_handle;
 476	  (void)attr_handle;
 477	
 478	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
 479	    {
 480	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
 481	      return 0;
 482	    }
 483	
 484	  pthread_mutex_lock(&g_state_lock);
 485	  generation = g_connection_generation;
 486	  pthread_mutex_unlock(&g_state_lock);
 487	
 488	  pthread_mutex_lock(&g_rx_lock);
 489	
 490	  if (g_rx_count >= PROBE_RX_QUEUE_DEPTH)
 491	    {
 492	      pthread_mutex_unlock(&g_rx_lock);
 493	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
 494	      return 0;
 495	    }
 496	
 497	  slot = &g_rx_queue[g_rx_head];
 498	  memcpy(&slot->addr, addr, sizeof(slot->addr));
 499	  slot->connection_generation = generation;
 500	  slot->length = length;
 501	  slot->offset = offset;
 502	  memcpy(slot->value, value, length);
 503	  g_rx_head = (g_rx_head + 1) % PROBE_RX_QUEUE_DEPTH;
 504	  g_rx_count++;
 505	  if (g_rx_count >
 506	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
 507	    {
 508	      __atomic_store_n(&g_rx_high_water, g_rx_count, __ATOMIC_RELAXED);
 509	    }
 510	  pthread_mutex_unlock(&g_rx_lock);
 511	
 512	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
 513	  sem_post(&g_rx_sem);
 514	  return length;
 515	}
 516	
 517	static void *probe_communication_thread(void *arg)
 518	{
 519	  struct probe_rx_slot_s slot;
 520	  bt_address_t peer_addr;
 521	  uint32_t generation;
 522	  uint32_t active_generation = 0;
 523	  bool connected;
 524	  bool have_slot;
 525	  int wait_status;
 526	
 527	  (void)arg;
 528	
 529	  for (;;)
 530	    {
 531	      do
 532	        {
 533	          wait_status = sem_wait(&g_rx_sem);
 534	        }
 535	      while (wait_status < 0 && errno == EINTR);
 536	
 537	      if (wait_status < 0)
 538	        {
 539	          continue;
 540	        }
 541	
 542	      pthread_mutex_lock(&g_rx_lock);
 543	      have_slot = g_rx_count > 0;
 544	      if (have_slot)
 545	        {
 546	          memcpy(&slot, &g_rx_queue[g_rx_tail], sizeof(slot));
 547	          g_rx_tail = (g_rx_tail + 1) % PROBE_RX_QUEUE_DEPTH;
 548	          g_rx_count--;
 549	        }
 550	      pthread_mutex_unlock(&g_rx_lock);
 551	
 552	      pthread_mutex_lock(&g_state_lock);
 553	      generation = g_connection_generation;
 554	      connected = g_peer_connected;
 555	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
 556	      pthread_mutex_unlock(&g_state_lock);
 557	
 558	      if (generation != active_generation)
 559	        {
 560	          memset(&g_throughput, 0, sizeof(g_throughput));
 561	          active_generation = generation;
 562	        }
 563	
 564	      if (!have_slot)
 565	        {
 566	          continue;
 567	        }
 568	
 569	      if (!connected || slot.connection_generation != generation ||
 570	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
 571	        {
 572	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
 573	          continue;
 574	        }
 575	
 590	    GATT_PERM_WRITE,
 591	    NULL, probe_rx_written, PROBE_RX_HANDLE),
 592	
 593	  GATT_H_CHARACTERISTIC_AUTO_RSP(
 594	    BT_UUID_DECLARE_16(PROBE_TX_UUID),
 595	    GATT_PROP_NOTIFY, 0, NULL, 0, PROBE_TX_HANDLE),
 596	
 597	  GATT_H_CCCD(GATT_PERM_READ | GATT_PERM_WRITE,
 598	              probe_tx_cccd_written, PROBE_TX_CCCD_HANDLE),
 599	};
