 613	  __atomic_store_n(&g_rx_enqueued, 0, __ATOMIC_RELAXED);
 614	  __atomic_store_n(&g_rx_invalid_length, 0, __ATOMIC_RELAXED);
 615	  __atomic_store_n(&g_rx_drop_lock_busy, 0, __ATOMIC_RELAXED);
 616	  __atomic_store_n(&g_rx_drop_full, 0, __ATOMIC_RELAXED);
 617	  __atomic_store_n(&g_rx_high_water, 0, __ATOMIC_RELAXED);
 618	  __atomic_store_n(&g_rx_stale, 0, __ATOMIC_RELAXED);
