 883	int main(int argc, char *argv[])
 884	{
 885	#if BLE_PROBE_ENABLE_AUTO_2M_PHY
 886	  bt_address_t peer_addr;
 887	#endif
 888	  bt_status_t status;
 889	  uint64_t startup_target_ms;
 890	#if BLE_PROBE_ENABLE_AUTO_2M_PHY
 891	  uint32_t generation;
 892	  bool do_phy_read;
 893	  bool do_phy_update;
 894	#endif
 895	  int ret;
 896	
 897	  if (probe_parse_startup_uptime(argc, argv, &startup_target_ms) < 0)
 898	    {
 899	      return 1;
 900	    }
 901	
 902	  if (probe_wait_for_ble_startup(startup_target_ms) < 0)
 903	    {
 904	      return 1;
 905	    }
 906	
 907	  sem_init(&g_ble_on_sem, 0, 0);
 908	
 909	  g_instance = bluetooth_create_instance();
 910	  if (g_instance == NULL)
 911	    {
 912	      printf("openvela_ble_probe: bluetooth_create_instance failed\n");
 913	      return 1;
 914	    }
 915	
 916	  if (bt_adapter_register_callback(g_instance, &g_adapter_callbacks) == NULL)
 917	    {
 918	      printf("openvela_ble_probe: callback registration failed\n");
 919	      return 1;
 920	    }
 921	
 922	  status = bt_adapter_enable_le(g_instance);
 923	  if (status != BT_STATUS_SUCCESS && status != BT_STATUS_DONE)
 924	    {
 925	      printf("openvela_ble_probe: bt_adapter_enable_le failed:%d\n",
 926	             status);
 927	      return 1;
 928	    }
 929	
 930	  if (bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_BLE_ON &&
 931	      bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_ON)
 932	    {
 933	      printf("openvela_ble_probe: waiting for BLE adapter\n");
 934	      sem_wait(&g_ble_on_sem);
 935	    }
 936	
 937	  ret = pthread_mutex_init(&g_state_lock, NULL);
 938	  if (ret != 0)
 939	    {
 940	      printf("openvela_ble_probe: state mutex init failed:%d\n", ret);
 941	      return 1;
 942	    }
 943	
 944	  ret = pthread_mutex_init(&g_rx_lock, NULL);
 945	  if (ret != 0)
 946	    {
 947	      printf("openvela_ble_probe: RX mutex init failed:%d\n", ret);
 948	      return 1;
 949	    }
 950	
 951	  if (sem_init(&g_rx_sem, 0, 0) < 0)
 952	    {
 953	      printf("openvela_ble_probe: RX semaphore init failed\n");
 954	      return 1;
 955	    }
 956	
 957	  if (init_gatt_service() < 0)
 958	    {
 959	      return 1;
 960	    }
 961	
 962	  ret = pthread_create(&g_communication_thread, NULL,
 963	                       probe_communication_thread, NULL);
 964	  if (ret != 0)
 965	    {
 966	      printf("openvela_ble_probe: communication thread create failed:%d\n",
 967	             ret);
 968	      return 1;
 969	    }
 970	
 971	  printf("openvela_ble_probe: delaying advertising 100 ms after GATT "
 972	         "table setup\n");
 973	  usleep(100000);
 974	
 975	  if (start_advertising() < 0)
 976	    {
 977	      return 1;
 978	    }
 979	
 980	  for (;;)
 981	    {
 982	      usleep(100000);
 983	
 984	#if BLE_PROBE_ENABLE_AUTO_2M_PHY
 985	      do_phy_read = false;
 986	      do_phy_update = false;
 987	
 988	      pthread_mutex_lock(&g_state_lock);
 989	      generation = g_connection_generation;
 990	      if (g_peer_connected && g_phy_read_pending &&
 991	          !g_phy_read_requested)
 992	        {
 993	          g_phy_read_pending = false;
 994	          g_phy_read_requested = true;
