   148	static int probe_wait_for_ble_startup(uint64_t target_ms)
   149	{
   150	  struct timespec now;
   151	  uint64_t uptime_ms;
   152	  uint64_t remaining_ms;
   153	  uint64_t sleep_ms;
   154	  bool delay_logged = false;
   155	
   156	  for (;;)
   157	    {
   158	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   159	        {
   160	          printf("openvela_ble_probe: failed to read system uptime\n");
   161	          return -1;
   162	        }
   163	
   164	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   165	                  (uint64_t)now.tv_nsec / 1000000u;
   166	      if (uptime_ms >= target_ms)
   167	        {
   168	          if (!delay_logged)
   169	            {
   170	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   171	                     "already satisfied\n",
   172	                     (unsigned long long)target_ms);
   173	            }
   174	
   175	          return 0;
   176	        }
   177	
   178	      remaining_ms = target_ms - uptime_ms;
   179	      if (!delay_logged)
   180	        {
   181	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   182	                 "for platform readiness (target=%llu ms)\n",
   183	                 (unsigned long long)remaining_ms,
   184	                 (unsigned long long)target_ms);
   185	          delay_logged = true;
   186	        }
   187	
   188	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
   189	      usleep((useconds_t)(sleep_ms * 1000u));
   190	    }
   191	}
