183	static void advertiser_start_event(void* data)
184	{
185	    assert(data);
186	    adv_event_t* start = (adv_event_t*)data;
187	    advertiser_t* adver = start->adver;
188	    advertising_info_t* adv_info = start->adv_info;
189	    int adv_id;
190	
191	    free(start);
192	    if (!adv_manager.started)
193	        return;
194	
195	    adv_id = index_alloc(adv_manager.adv_allocator);
196	    if (adv_id < 0) {
197	        adver->callbacks.on_advertising_start(get_adver(adver), 0, BT_ADV_STATUS_START_NOMEM);
198	        goto fail;
199	    }
200	
201	    adver->adv_id = adv_id + 1;
202	    if (bt_sal_le_start_adv(0, adver->adv_id, &adv_info->params, adv_info->adv_data,
203	            adv_info->adv_len, adv_info->scan_rsp_data,
204	            adv_info->scan_rsp_len)
205	        != BT_STATUS_SUCCESS) {
206	        adver->callbacks.on_advertising_start(get_adver(adver), 0, BT_ADV_STATUS_STACK_ERR);
207	        goto fail;
208	    }
209	
210	    list_add_tail(&adv_manager.advertiser_list, &adver->adver_node);
211	    advertiser_info_free(adv_info);
212	    adver->adv_start = service_loop_timer_no_repeating(1000, start_advertising_timeout, adver);
213	
214	    return;
215	fail:
216	    destroy_advertiser(adver);
217	    advertiser_info_free(adv_info);
218	}
